-- OnlinePOS complete PostgreSQL fresh-database setup.
-- Generated by tools/export-database-setup.py; edit migrations, then regenerate.
-- Use an EMPTY, dedicated local database. This is not an upgrade script.
-- Do not run this manually against an application-managed database.
-- Includes migration seed/configuration rows; no customer or order exports.
-- Does not create database users, credentials, or Flyway history.
-- See docs/database/README.md before use.

BEGIN;

-- BEGIN V1__local_authority.sql
-- New LOCAL schema only. Never run against the operational cloud database.
CREATE SCHEMA pos;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON SCHEMA pos FROM PUBLIC;
CREATE TABLE pos.store_identity (
  singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
  branch_id integer NOT NULL UNIQUE CHECK(branch_id IN (1,2)),
  cluster_id uuid NOT NULL UNIQUE,
  installation_id uuid NOT NULL UNIQUE
);
CREATE TABLE pos.staff (
  staff_id uuid PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  username varchar(64) NOT NULL CHECK(username = lower(username)),
  password_hash text NOT NULL,
  role varchar(16) NOT NULL CHECK(role IN ('MANAGER','CASHIER')),
  enabled boolean NOT NULL DEFAULT true,
  credential_version bigint NOT NULL DEFAULT 0,
  failed_attempts integer NOT NULL DEFAULT 0,
  locked_until timestamptz,
  revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
  UNIQUE(branch_id, username), UNIQUE(branch_id,staff_id)
);
CREATE TABLE pos.staff_session (
  token_hash char(64) PRIMARY KEY,
  branch_id integer NOT NULL,
  staff_id uuid NOT NULL,
  terminal_identity varchar(512) NOT NULL,
  credential_version bigint NOT NULL,
  expires_at timestamptz NOT NULL,
  FOREIGN KEY(branch_id,staff_id) REFERENCES pos.staff(branch_id,staff_id)
);
CREATE TABLE pos.catalog_item (
  item_id uuid PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  source_type varchar(40) NOT NULL,
  source_id varchar(128) NOT NULL,
  description varchar(256) NOT NULL,
  definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),
  definition_revision bigint NOT NULL CHECK(definition_revision>=0),
  UNIQUE(branch_id,source_type,source_id), UNIQUE(branch_id,item_id)
);
CREATE TABLE pos.branch_price (
  price_id uuid PRIMARY KEY,
  branch_id integer NOT NULL,
  item_id uuid NOT NULL,
  variant_key varchar(128) NOT NULL,
  amount numeric(19,2) NOT NULL CHECK(amount>=0),
  available boolean NOT NULL,
  revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
  FOREIGN KEY(branch_id,item_id) REFERENCES pos.catalog_item(branch_id,item_id),
  UNIQUE(branch_id,item_id,variant_key), UNIQUE(branch_id,price_id)
);
CREATE TABLE pos.local_customer (
  customer_id uuid PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  display_name varchar(128) NOT NULL,
  phone varchar(64), address text,
  address_verified boolean NOT NULL DEFAULT false,
  revision bigint NOT NULL DEFAULT 0,
  UNIQUE(branch_id,customer_id)
);
-- Drafts are not accepted sales. Fulfilment/payment acceptance is Stage 5.
CREATE TABLE pos.order_draft (
  sync_id uuid PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  internal_id bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
  customer_id uuid,
  state varchar(16) NOT NULL CHECK(state IN ('DRAFT','CANCELLED')),
  revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
  provisional_reference varchar(128) NOT NULL UNIQUE,
  final_reference varchar(128),
  total numeric(19,2) NOT NULL CHECK(total>=0),
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  FOREIGN KEY(branch_id,customer_id) REFERENCES pos.local_customer(branch_id,customer_id),
  UNIQUE(branch_id,sync_id)
);
CREATE TABLE pos.order_line (
  line_id uuid PRIMARY KEY,
  branch_id integer NOT NULL,
  order_id uuid NOT NULL,
  price_id uuid NOT NULL,
  description varchar(256) NOT NULL,
  quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 999),
  unit_price numeric(19,2) NOT NULL CHECK(unit_price>=0),
  price_revision bigint NOT NULL,
  snapshot jsonb NOT NULL,
  FOREIGN KEY(branch_id,order_id) REFERENCES pos.order_draft(branch_id,sync_id),
  FOREIGN KEY(branch_id,price_id) REFERENCES pos.branch_price(branch_id,price_id),
  UNIQUE(branch_id,line_id)
);
CREATE TABLE pos.order_line_extra (
  extra_id uuid PRIMARY KEY,
  branch_id integer NOT NULL,
  line_id uuid NOT NULL,
  snapshot jsonb NOT NULL,
  amount numeric(19,2) NOT NULL CHECK(amount>=0),
  FOREIGN KEY(branch_id,line_id) REFERENCES pos.order_line(branch_id,line_id)
);
CREATE TABLE pos.payment_metadata (
  payment_id uuid PRIMARY KEY,
  branch_id integer NOT NULL,
  order_id uuid NOT NULL,
  method varchar(24) NOT NULL CHECK(method IN ('CASH','EXTERNAL_CARD')),
  amount numeric(19,2) NOT NULL CHECK(amount>=0),
  external_reference varchar(128),
  FOREIGN KEY(branch_id,order_id) REFERENCES pos.order_draft(branch_id,sync_id)
);
CREATE TABLE pos.command_receipt (
  command_id uuid PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  actor_id uuid NOT NULL,
  terminal_identity varchar(512) NOT NULL,
  payload_hash char(64) NOT NULL,
  result jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE pos.stream_head (
  branch_id integer PRIMARY KEY REFERENCES pos.store_identity(branch_id),
  position bigint NOT NULL DEFAULT 0
);
CREATE TABLE pos.audit_record (
  audit_id uuid PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  actor_id uuid NOT NULL,
  action varchar(64) NOT NULL,
  aggregate_id uuid NOT NULL,
  command_id uuid,
  details jsonb NOT NULL,
  occurred_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE pos.outbox_event (
  event_id uuid PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  stream_position bigint NOT NULL,
  aggregate_id uuid NOT NULL,
  aggregate_revision bigint NOT NULL,
  event_type varchar(64) NOT NULL,
  payload jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(branch_id,stream_position)
);
CREATE TABLE pos.inbox_receipt (
  event_id uuid PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  payload_hash char(64) NOT NULL,
  result jsonb NOT NULL,
  received_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE pos.terminal_printer (
  terminal_identity varchar(512) PRIMARY KEY,
  branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
  printer_name varchar(256),
  revision bigint NOT NULL DEFAULT 0
);
GRANT USAGE ON SCHEMA pos TO pos_runtime;
GRANT SELECT ON ALL TABLES IN SCHEMA pos TO pos_runtime;
GRANT INSERT,UPDATE,DELETE ON pos.staff_session TO pos_runtime;
GRANT INSERT,UPDATE ON pos.staff, pos.branch_price, pos.local_customer, pos.order_draft, pos.stream_head, pos.terminal_printer TO pos_runtime;
GRANT INSERT ON pos.order_line, pos.order_line_extra, pos.payment_metadata, pos.command_receipt, pos.audit_record, pos.outbox_event, pos.inbox_receipt TO pos_runtime;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA pos TO pos_runtime;
-- END V1__local_authority.sql

-- BEGIN V2__catalogue_bootstrap.sql
-- Additive LOCAL migration. Initial imports cannot overwrite existing data.
CREATE TABLE pos.catalogue_bootstrap (
  branch_id integer PRIMARY KEY REFERENCES pos.store_identity(branch_id),
  snapshot_id uuid NOT NULL UNIQUE,
  sha256 char(64) NOT NULL,
  snapshot jsonb NOT NULL,
  cutover_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
GRANT SELECT ON pos.catalogue_bootstrap TO pos_runtime;
-- Narrow one-shot write port retains the runtime prohibition on catalogue INSERT/DDL.
CREATE FUNCTION pos.bootstrap_catalogue(p_branch integer, p_id uuid, p_hash text,
    p_snapshot jsonb, p_items jsonb, p_prices jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pos AS $$
BEGIN
  IF p_hash !~ '^[a-f0-9]{64}$' OR (p_snapshot->>'branchId')::integer <> p_branch
      OR (p_snapshot->>'snapshotId')::uuid <> p_id
      OR jsonb_array_length(p_items)=0 OR jsonb_array_length(p_prices)=0 THEN
    RAISE EXCEPTION 'Invalid bootstrap envelope' USING ERRCODE='23514';
  END IF;
  PERFORM position FROM pos.stream_head WHERE branch_id=p_branch FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown branch'; END IF;
  IF EXISTS (SELECT 1 FROM pos.catalogue_bootstrap)
     OR EXISTS (SELECT 1 FROM pos.catalog_item)
     OR EXISTS (SELECT 1 FROM pos.branch_price)
     OR EXISTS (SELECT 1 FROM pos.order_draft) THEN
    RAISE EXCEPTION 'Bootstrap requires empty catalogue and orders' USING ERRCODE='23505';
  END IF;
  INSERT INTO pos.catalog_item(item_id,branch_id,source_type,source_id,description,definition,definition_revision)
    SELECT item_id,p_branch,source_type,source_id,description,definition,0
    FROM jsonb_to_recordset(p_items) AS x(item_id uuid,source_type text,source_id text,description text,definition jsonb);
  INSERT INTO pos.branch_price(price_id,branch_id,item_id,variant_key,amount,available,revision)
    SELECT price_id,p_branch,item_id,'baseline',amount,available,0
    FROM jsonb_to_recordset(p_prices) AS x(price_id uuid,item_id uuid,amount numeric,available boolean);
  INSERT INTO pos.catalogue_bootstrap(branch_id,snapshot_id,sha256,snapshot)
    VALUES(p_branch,p_id,p_hash,p_snapshot);
END $$;
REVOKE ALL ON FUNCTION pos.bootstrap_catalogue(integer,uuid,text,jsonb,jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.bootstrap_catalogue(integer,uuid,text,jsonb,jsonb,jsonb) TO pos_runtime;
-- END V2__catalogue_bootstrap.sql

-- BEGIN V3__module_rbac.sql
-- Additive local-only RBAC. No default staff PINs.
CREATE TABLE pos.rbac_role (
 branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
 name varchar(64) NOT NULL, PRIMARY KEY(branch_id,name)
);
CREATE TABLE pos.role_permission (
 branch_id integer NOT NULL, role_name varchar(64) NOT NULL,
 permission varchar(80) NOT NULL, PRIMARY KEY(branch_id,role_name,permission),
 FOREIGN KEY(branch_id,role_name) REFERENCES pos.rbac_role(branch_id,name) ON DELETE CASCADE
);
CREATE TABLE pos.staff_role (
 branch_id integer NOT NULL, staff_id uuid NOT NULL, role_name varchar(64) NOT NULL,
 PRIMARY KEY(branch_id,staff_id,role_name),
 FOREIGN KEY(branch_id,staff_id) REFERENCES pos.staff(branch_id,staff_id) ON DELETE CASCADE,
 FOREIGN KEY(branch_id,role_name) REFERENCES pos.rbac_role(branch_id,name)
);
CREATE TABLE pos.staff_pin (
 branch_id integer NOT NULL, staff_id uuid NOT NULL, lookup char(64) NOT NULL, hash text NOT NULL,
 PRIMARY KEY(branch_id,staff_id), UNIQUE(branch_id,lookup),
 FOREIGN KEY(branch_id,staff_id) REFERENCES pos.staff(branch_id,staff_id) ON DELETE CASCADE
);
CREATE TABLE pos.module_session (
 token_hash char(64) PRIMARY KEY, branch_id integer NOT NULL, staff_id uuid NOT NULL,
 terminal_identity varchar(512) NOT NULL, module varchar(32) NOT NULL,
 credential_version bigint NOT NULL, expires_at timestamptz NOT NULL,
 FOREIGN KEY(branch_id,staff_id) REFERENCES pos.staff(branch_id,staff_id) ON DELETE CASCADE
);
CREATE TABLE pos.pin_throttle (
 branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
 scope varchar(520) NOT NULL, failures integer NOT NULL DEFAULT 0,
 window_start timestamptz NOT NULL DEFAULT clock_timestamp(), locked_until timestamptz,
 PRIMARY KEY(branch_id,scope)
);
-- Also seed branches created after this migration, and preserve legacy staff defaults.
CREATE FUNCTION pos.seed_rbac() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pos AS $$
BEGIN
 INSERT INTO pos.rbac_role VALUES (NEW.branch_id,'MANAGER'),(NEW.branch_id,'CASHIER');
 INSERT INTO pos.role_permission SELECT NEW.branch_id,'MANAGER',p FROM unnest(ARRAY[
 'module.sales_orders','module.customers','module.catalogue','module.cash','module.reports','module.administration',
 'staff.manage','rbac.manage']) p;
 INSERT INTO pos.role_permission VALUES (NEW.branch_id,'CASHIER','module.sales_orders');
 RETURN NEW;
END $$;
CREATE TRIGGER seed_rbac AFTER INSERT ON pos.store_identity FOR EACH ROW EXECUTE FUNCTION pos.seed_rbac();
INSERT INTO pos.rbac_role SELECT branch_id,r FROM pos.store_identity CROSS JOIN unnest(ARRAY['MANAGER','CASHIER']) r;
INSERT INTO pos.role_permission SELECT branch_id,'MANAGER',p FROM pos.store_identity CROSS JOIN unnest(ARRAY[
 'module.sales_orders','module.customers','module.catalogue','module.cash','module.reports','module.administration',
 'staff.manage','rbac.manage']) p;
INSERT INTO pos.role_permission SELECT branch_id,'CASHIER','module.sales_orders' FROM pos.store_identity;
INSERT INTO pos.staff_role SELECT branch_id,staff_id,role FROM pos.staff;
CREATE FUNCTION pos.staff_default_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.role=NEW.role THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN DELETE FROM pos.staff_role WHERE staff_id=NEW.staff_id AND role_name=OLD.role; END IF;
 INSERT INTO pos.staff_role VALUES(NEW.branch_id,NEW.staff_id,NEW.role) ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;
CREATE TRIGGER staff_default_role AFTER INSERT OR UPDATE OF role ON pos.staff FOR EACH ROW EXECUTE FUNCTION pos.staff_default_role();
GRANT SELECT ON pos.rbac_role,pos.role_permission,pos.staff_role,pos.staff_pin TO pos_runtime;
GRANT SELECT,INSERT,UPDATE,DELETE ON pos.module_session,pos.pin_throttle TO pos_runtime;
REVOKE ALL ON FUNCTION pos.staff_default_role() FROM PUBLIC;
REVOKE ALL ON FUNCTION pos.seed_rbac() FROM PUBLIC;

CREATE FUNCTION pos.invalidate_module_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer; target_staff uuid; target_role varchar(64);
BEGIN
 b=COALESCE(NEW.branch_id,OLD.branch_id);
 IF TG_TABLE_NAME='role_permission' THEN
   target_role=COALESCE(NEW.role_name,OLD.role_name);
   DELETE FROM pos.module_session WHERE branch_id=b AND staff_id IN (SELECT staff_id FROM pos.staff_role WHERE branch_id=b AND role_name=target_role);
   DELETE FROM pos.staff_session WHERE branch_id=b AND staff_id IN (SELECT staff_id FROM pos.staff_role WHERE branch_id=b AND role_name=target_role);
 ELSE
   target_staff=COALESCE(NEW.staff_id,OLD.staff_id);
   DELETE FROM pos.module_session WHERE branch_id=b AND staff_id=target_staff;
   DELETE FROM pos.staff_session WHERE branch_id=b AND staff_id=target_staff;
 END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER invalidate_roles AFTER INSERT OR UPDATE OR DELETE ON pos.staff_role FOR EACH ROW EXECUTE FUNCTION pos.invalidate_module_access();
CREATE TRIGGER invalidate_permissions AFTER INSERT OR UPDATE OR DELETE ON pos.role_permission FOR EACH ROW EXECUTE FUNCTION pos.invalidate_module_access();
CREATE TRIGGER invalidate_pins AFTER INSERT OR UPDATE OR DELETE ON pos.staff_pin FOR EACH ROW EXECUTE FUNCTION pos.invalidate_module_access();
CREATE TRIGGER invalidate_staff AFTER UPDATE OF password_hash,credential_version,enabled,role,username OR DELETE ON pos.staff FOR EACH ROW EXECUTE FUNCTION pos.invalidate_module_access();
CREATE FUNCTION pos.guard_rbac_administrator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;
BEGIN
 b=COALESCE(NEW.branch_id,OLD.branch_id);
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 IF (EXISTS(SELECT 1 FROM pos.staff WHERE branch_id=b) OR (TG_TABLE_NAME='staff' AND TG_OP='DELETE')) AND NOT EXISTS(
 SELECT 1 FROM pos.staff s JOIN pos.staff_role r ON r.staff_id=s.staff_id AND r.branch_id=s.branch_id
 JOIN pos.role_permission p ON p.branch_id=r.branch_id AND p.role_name=r.role_name
 WHERE s.branch_id=b AND s.enabled AND p.permission='rbac.manage') THEN
 RAISE EXCEPTION 'The final enabled RBAC administrator cannot be removed' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER guard_staff_rbac AFTER INSERT OR UPDATE OR DELETE ON pos.staff DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pos.guard_rbac_administrator();
CREATE CONSTRAINT TRIGGER guard_assignments_rbac AFTER INSERT OR UPDATE OR DELETE ON pos.staff_role DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pos.guard_rbac_administrator();
CREATE CONSTRAINT TRIGGER guard_permissions_rbac AFTER INSERT OR UPDATE OR DELETE ON pos.role_permission DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pos.guard_rbac_administrator();
REVOKE ALL ON FUNCTION pos.invalidate_module_access(),pos.guard_rbac_administrator() FROM PUBLIC;
-- END V3__module_rbac.sql

-- BEGIN V4__administration.sql
-- Local administration only. No implicit owner and no default staff PINs.
ALTER TABLE pos.staff ADD COLUMN password_login_enabled boolean NOT NULL DEFAULT true;
ALTER TABLE pos.rbac_role ADD COLUMN revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0);
CREATE TABLE pos.store_owner (
 branch_id integer PRIMARY KEY REFERENCES pos.store_identity(branch_id),
 staff_id uuid NOT NULL,
 FOREIGN KEY(branch_id,staff_id) REFERENCES pos.staff(branch_id,staff_id)
);
GRANT SELECT ON pos.store_owner TO pos_runtime;
INSERT INTO pos.role_permission SELECT branch_id,name,'audit.view' FROM pos.rbac_role WHERE name='MANAGER' ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION pos.seed_rbac() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pos AS $$
BEGIN
 INSERT INTO pos.rbac_role(branch_id,name) VALUES(NEW.branch_id,'MANAGER'),(NEW.branch_id,'CASHIER');
 INSERT INTO pos.role_permission SELECT NEW.branch_id,'MANAGER',p FROM unnest(ARRAY[
 'module.sales_orders','module.customers','module.catalogue','module.cash','module.reports','module.administration',
 'staff.manage','rbac.manage','audit.view']) p;
 INSERT INTO pos.role_permission VALUES(NEW.branch_id,'CASHIER','module.sales_orders');
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION pos.guard_rbac_administrator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;
BEGIN
 IF TG_TABLE_NAME='staff' AND TG_OP='UPDATE' THEN
  IF OLD.enabled=NEW.enabled AND OLD.role=NEW.role THEN RETURN NULL; END IF;
 END IF;
 b=COALESCE(NEW.branch_id,OLD.branch_id);
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 IF (EXISTS(SELECT 1 FROM pos.staff WHERE branch_id=b) OR (TG_TABLE_NAME='staff' AND TG_OP='DELETE')) AND NOT EXISTS(
 SELECT 1 FROM pos.staff s WHERE s.branch_id=b AND s.enabled AND (
 EXISTS(SELECT 1 FROM pos.store_owner o WHERE o.branch_id=b AND o.staff_id=s.staff_id) OR
 EXISTS(SELECT 1 FROM pos.staff_role r JOIN pos.role_permission p ON p.branch_id=r.branch_id AND p.role_name=r.role_name
 WHERE r.staff_id=s.staff_id AND r.branch_id=b AND p.permission='rbac.manage'))) THEN
 RAISE EXCEPTION 'The final enabled RBAC administrator cannot be removed' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;
CREATE FUNCTION pos.protect_store_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pos AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM pos.store_owner WHERE branch_id=OLD.branch_id AND staff_id=OLD.staff_id) THEN
   IF TG_OP='DELETE' OR NOT NEW.enabled THEN
     RAISE EXCEPTION 'Transfer ownership before disabling the owner' USING ERRCODE='23514';
   END IF;
   IF current_user<>'pos_owner' THEN
     RAISE EXCEPTION 'Owner account requires protected administration' USING ERRCODE='42501';
   END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER protect_store_owner BEFORE UPDATE OF username,password_hash,password_login_enabled,enabled,role,credential_version OR DELETE ON pos.staff FOR EACH ROW EXECUTE FUNCTION pos.protect_store_owner();
CREATE FUNCTION pos.owner_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pos.staff WHERE branch_id=NEW.branch_id AND staff_id=NEW.staff_id AND enabled) THEN
  RAISE EXCEPTION 'Owner must be enabled' USING ERRCODE='23514';
 END IF;
 UPDATE pos.staff SET credential_version=credential_version+1 WHERE branch_id=NEW.branch_id AND staff_id IN (NEW.staff_id,OLD.staff_id);
 RETURN NULL;
END $$;
CREATE TRIGGER owner_changed AFTER INSERT OR UPDATE ON pos.store_owner FOR EACH ROW EXECUTE FUNCTION pos.owner_changed();
DROP TRIGGER invalidate_staff ON pos.staff;
CREATE TRIGGER invalidate_staff AFTER UPDATE OF password_hash,password_login_enabled,credential_version,enabled,role,username OR DELETE ON pos.staff FOR EACH ROW EXECUTE FUNCTION pos.invalidate_module_access();
CREATE FUNCTION pos.admin_permissions(b integer,who uuid) RETURNS SETOF text LANGUAGE sql STABLE SET search_path=pg_catalog,pos AS $$
 SELECT p.permission::text FROM pos.staff_role r JOIN pos.role_permission p ON p.branch_id=r.branch_id AND p.role_name=r.role_name WHERE r.branch_id=b AND r.staff_id=who
 UNION SELECT p FROM unnest(ARRAY['module.administration','staff.manage','rbac.manage','audit.view']) p WHERE EXISTS(SELECT 1 FROM pos.store_owner WHERE branch_id=b AND staff_id=who)
$$;
-- Functions accept a hashed, live terminal-bound session, never a caller-supplied actor identity.
CREATE FUNCTION pos.require_admin_session(proof text,terminal text,required_permission text,owner_only boolean) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE who uuid; b integer;
BEGIN
 SELECT t.staff_id,t.branch_id INTO who,b FROM pos.module_session t JOIN pos.staff s ON s.staff_id=t.staff_id AND s.branch_id=t.branch_id
 WHERE t.token_hash=proof AND t.terminal_identity=terminal AND t.module='ADMINISTRATION' AND t.expires_at>clock_timestamp() AND s.enabled AND t.credential_version=s.credential_version;
 IF who IS NULL THEN RAISE EXCEPTION 'Administration session required' USING ERRCODE='28000'; END IF;
 IF required_permission NOT IN (SELECT pos.admin_permissions(b,who)) OR
 (owner_only AND NOT EXISTS(SELECT 1 FROM pos.store_owner WHERE branch_id=b AND staff_id=who)) THEN
  RAISE EXCEPTION 'Administration permission required' USING ERRCODE='42501';
 END IF;
 RETURN who;
END $$;
CREATE FUNCTION pos.apply_admin_change(proof text,terminal text,kind text,data jsonb) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE who uuid; b integer; target uuid; old_revision bigint; next_revision bigint; owner_actor boolean; requested text[]; r text;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 who=pos.require_admin_session(proof,terminal,CASE kind WHEN 'role' THEN 'rbac.manage' ELSE 'staff.manage' END,kind='pin');
 owner_actor=EXISTS(SELECT 1 FROM pos.store_owner WHERE branch_id=b AND staff_id=who);
 IF kind='role' THEN
  IF (data->>'name') !~ '^[A-Z][A-Z0-9_]{0,63}$' THEN RAISE EXCEPTION 'Invalid role' USING ERRCODE='23514'; END IF;
  SELECT array_agg(v) INTO requested FROM jsonb_array_elements_text(data->'permissions') v;
  requested=coalesce(requested,ARRAY[]::text[]);
  IF EXISTS(SELECT 1 FROM unnest(requested) p WHERE p NOT IN ('module.sales_orders','module.customers','module.catalogue','module.cash','module.reports','module.administration','staff.manage','rbac.manage','audit.view')) THEN
   RAISE EXCEPTION 'Unsupported permission' USING ERRCODE='23514';
  END IF;
  IF NOT owner_actor AND EXISTS(SELECT 1 FROM unnest(requested) p WHERE p NOT IN (SELECT pos.admin_permissions(b,who))) THEN
   RAISE EXCEPTION 'Cannot delegate an unheld permission' USING ERRCODE='42501';
  END IF;
  SELECT revision INTO old_revision FROM pos.rbac_role WHERE branch_id=b AND name=data->>'name';
  IF (old_revision IS NULL AND (data->>'expectedRevision')::bigint<>-1) OR
     (old_revision IS NOT NULL AND old_revision<>(data->>'expectedRevision')::bigint) THEN
    RAISE EXCEPTION 'Role changed; reload' USING ERRCODE='23514';
  END IF;
  -- Non-owners cannot strip permissions from a more privileged existing role either.
  IF NOT owner_actor AND EXISTS(SELECT 1 FROM pos.role_permission WHERE branch_id=b AND role_name=data->>'name' AND permission NOT IN (SELECT pos.admin_permissions(b,who))) THEN
   RAISE EXCEPTION 'Cannot modify a more privileged role' USING ERRCODE='42501';
  END IF;
  next_revision=coalesce(old_revision+1,0);
  INSERT INTO pos.rbac_role(branch_id,name,revision) VALUES(b,data->>'name',next_revision) ON CONFLICT(branch_id,name) DO UPDATE SET revision=excluded.revision;
  DELETE FROM pos.role_permission WHERE branch_id=b AND role_name=data->>'name';
  INSERT INTO pos.role_permission SELECT DISTINCT b,data->>'name',p FROM unnest(requested) p;
  RETURN next_revision;
 END IF;
 target=(data->>'staffId')::uuid;
 SELECT revision INTO old_revision FROM pos.staff WHERE branch_id=b AND staff_id=target;
 IF old_revision IS NOT NULL AND old_revision<>(data->>'expectedRevision')::bigint THEN
  RAISE EXCEPTION 'Staff changed; reload' USING ERRCODE='23514';
 END IF;
 IF EXISTS(SELECT 1 FROM pos.store_owner WHERE branch_id=b AND staff_id=target) AND (NOT owner_actor OR NOT (data->>'enabled')::boolean AND kind='staff') THEN
  RAISE EXCEPTION 'Owner account is protected' USING ERRCODE='42501';
 END IF;
 IF kind='pin' THEN
  IF old_revision IS NULL THEN RAISE EXCEPTION 'Unknown staff' USING ERRCODE='23514'; END IF;
  IF (data->>'lookup') !~ '^[a-f0-9]{64}$' OR (data->>'hash') NOT LIKE '600000:%' THEN RAISE EXCEPTION 'Invalid PIN credential' USING ERRCODE='23514'; END IF;
  INSERT INTO pos.staff_pin VALUES(b,target,data->>'lookup',data->>'hash') ON CONFLICT(branch_id,staff_id) DO UPDATE SET lookup=excluded.lookup,hash=excluded.hash;
 ELSE
  IF kind<>'staff' OR (data->>'username') !~ '^[a-z0-9._-]{3,64}$' OR (old_revision IS NULL AND (data->>'expectedRevision')::bigint<>-1) THEN RAISE EXCEPTION 'Invalid staff' USING ERRCODE='23514'; END IF;
  SELECT array_agg(v) INTO requested FROM jsonb_array_elements_text(data->'roles') v;
  IF coalesce(array_length(requested,1),0)=0 OR EXISTS(SELECT 1 FROM unnest(requested) n WHERE NOT EXISTS(SELECT 1 FROM pos.rbac_role WHERE branch_id=b AND name=n)) THEN
   RAISE EXCEPTION 'Valid roles required' USING ERRCODE='23514';
  END IF;
  IF NOT owner_actor AND EXISTS(SELECT 1 FROM pos.role_permission WHERE branch_id=b AND role_name=ANY(requested) AND permission NOT IN (SELECT pos.admin_permissions(b,who))) THEN
   RAISE EXCEPTION 'Cannot assign a more privileged role' USING ERRCODE='42501';
  END IF;
  IF NOT owner_actor AND EXISTS(SELECT 1 FROM pos.staff_role sr JOIN pos.role_permission rp ON rp.branch_id=sr.branch_id AND rp.role_name=sr.role_name WHERE sr.branch_id=b AND sr.staff_id=target AND rp.permission NOT IN (SELECT pos.admin_permissions(b,who))) THEN
   RAISE EXCEPTION 'Cannot modify more privileged staff' USING ERRCODE='42501';
  END IF;
  IF old_revision IS NULL THEN
   INSERT INTO pos.staff(staff_id,branch_id,username,password_hash,password_login_enabled,role,enabled) VALUES(target,b,data->>'username',data->>'unusablePasswordHash',false,'CASHIER',(data->>'enabled')::boolean);
  ELSE
   UPDATE pos.staff SET username=data->>'username',enabled=(data->>'enabled')::boolean WHERE branch_id=b AND staff_id=target;
  END IF;
  DELETE FROM pos.staff_role WHERE branch_id=b AND staff_id=target;
  INSERT INTO pos.staff_role SELECT DISTINCT b,target,n FROM unnest(requested) n;
 END IF;
 next_revision=coalesce(old_revision+1,0);
 UPDATE pos.staff SET credential_version=credential_version+1,revision=next_revision WHERE branch_id=b AND staff_id=target;
 RETURN next_revision;
END $$;
REVOKE ALL ON FUNCTION pos.admin_permissions(integer,uuid),pos.require_admin_session(text,text,text,boolean),pos.apply_admin_change(text,text,text,jsonb),pos.protect_store_owner(),pos.owner_changed() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.admin_permissions(integer,uuid),pos.apply_admin_change(text,text,text,jsonb) TO pos_runtime;
-- END V4__administration.sql

-- BEGIN V5__catalogue_management.sql
-- Local editable working records. The immutable bootstrap snapshot remains untouched.
CREATE TABLE pos.catalogue_version (
 branch_id integer PRIMARY KEY REFERENCES pos.catalogue_bootstrap(branch_id),
 revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0)
);
CREATE TABLE pos.catalogue_record (
 branch_id integer NOT NULL REFERENCES pos.catalogue_version(branch_id),
 source_type varchar(40) NOT NULL,
 source_id varchar(128) NOT NULL,
 data jsonb NOT NULL CHECK(jsonb_typeof(data)='object'),
 PRIMARY KEY(branch_id,source_type,source_id)
);
CREATE SEQUENCE pos.catalogue_local_id START WITH 1000000000 MAXVALUE 2147483647;
GRANT USAGE ON SEQUENCE pos.catalogue_local_id TO pos_runtime;
GRANT SELECT ON pos.catalogue_version,pos.catalogue_record TO pos_runtime;
CREATE FUNCTION pos.initialize_catalogue_records(p_branch integer,p_tables jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE t record; r jsonb;
BEGIN
 INSERT INTO pos.catalogue_version(branch_id) VALUES(p_branch);
 -- Source keys are retained exactly as imported by CatalogueImport/SnapshotFormat.
 FOR t IN SELECT key,value FROM jsonb_each(p_tables) LOOP
  FOR r IN SELECT value FROM jsonb_array_elements(t.value) LOOP
   INSERT INTO pos.catalogue_record VALUES(p_branch,t.key,
    replace((CASE t.key
     WHEN 'branch' THEN jsonb_build_array(r->'branch_id')
     WHEN 'branch_menu_item_price' THEN jsonb_build_array(r->'branch_id',r->'menu_item_id')
     WHEN 'menu_item_modifier_group' THEN jsonb_build_array(r->'menu_item_id',r->'group_id')
     WHEN 'burger_component' THEN jsonb_build_array(r->'component_id')
     WHEN 'burger_recipe' THEN jsonb_build_array(r->'recipe_id')
     WHEN 'burger_recipe_component' THEN jsonb_build_array(r->'recipe_id',r->'component_id')
     WHEN 'burger_recipe_assignment' THEN jsonb_build_array(r->'burger_id')
     WHEN 'burger_item_default_component' THEN jsonb_build_array(r->'burger_id',r->'component_id')
     WHEN 'branch_burger_component_price' THEN jsonb_build_array(r->'branch_id',r->'component_id')
     WHEN 'pizza_category' THEN jsonb_build_array(r->'pizza_category_id')
     WHEN 'pizza' THEN jsonb_build_array(r->'pizza_id')
     WHEN 'pizza_size' THEN jsonb_build_array(r->'pizza_size_id')
     WHEN 'pizza_allowed_size' THEN jsonb_build_array(r->'pizza_id',r->'pizza_size_id')
     WHEN 'price_category' THEN jsonb_build_array(r->'price_category_id')
     WHEN 'ingredient' THEN jsonb_build_array(r->'ingredient_id')
     WHEN 'pizza_default_ingredient' THEN jsonb_build_array(r->'pizza_id',r->'ingredient_id')
     WHEN 'branch_pizza_price' THEN jsonb_build_array(r->'branch_id',r->'pizza_id',r->'pizza_size_id')
     WHEN 'branch_extra_price' THEN jsonb_build_array(r->'branch_id',r->'price_category_id',r->'pizza_size_id')
     WHEN 'pizza_base_option' THEN jsonb_build_array(r->'pizza_base_option_id')
     WHEN 'branch_pizza_base_option_price' THEN jsonb_build_array(r->'branch_id',r->'pizza_base_option_id',r->'pizza_size_id')
     WHEN 'special' THEN jsonb_build_array(r->'special_id')
     WHEN 'special_day' THEN jsonb_build_array(r->'special_id',r->'day_of_week')
     WHEN 'special_component' THEN jsonb_build_array(r->'special_component_id')
     WHEN 'special_component_menu_item' THEN jsonb_build_array(r->'special_component_id',r->'menu_item_id')
     WHEN 'special_component_pizza' THEN jsonb_build_array(r->'special_component_id',r->'pizza_id')
     WHEN 'special_addon' THEN jsonb_build_array(r->'special_addon_id')
     ELSE jsonb_build_array(r->'id') END)::text,' ','') ,r);
  END LOOP;
 END LOOP;
 RETURN;
END $$;
CREATE FUNCTION pos.seed_catalogue_records() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
BEGIN
 PERFORM pos.initialize_catalogue_records(NEW.branch_id,NEW.snapshot->'tables');
 RETURN NULL;
END $$;
CREATE TRIGGER seed_catalogue_records AFTER INSERT ON pos.catalogue_bootstrap
 FOR EACH ROW EXECUTE FUNCTION pos.seed_catalogue_records();
-- Initialize existing stores without issuing any UPDATE to their immutable import.
DO $$ DECLARE b record; BEGIN
 FOR b IN SELECT branch_id,snapshot FROM pos.catalogue_bootstrap LOOP
  PERFORM pos.initialize_catalogue_records(b.branch_id,b.snapshot->'tables');
 END LOOP;
END $$;
-- Extend only the implemented action allowlist; no default role receives editing rights.
DO $$ DECLARE definition text; BEGIN
 SELECT pg_get_functiondef('pos.apply_admin_change(text,text,text,jsonb)'::regprocedure) INTO definition;
 definition=replace(definition,'''staff.manage'',''rbac.manage'',''audit.view''','''staff.manage'',''rbac.manage'',''audit.view'',''catalogue.manage''');
 EXECUTE definition;
END $$;
CREATE FUNCTION pos.apply_catalogue_change(proof text,terminal text,expected bigint,records jsonb,prices jsonb) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer; who uuid; version bigint;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 SELECT t.staff_id INTO who FROM pos.module_session t JOIN pos.staff s USING(branch_id,staff_id)
 WHERE t.branch_id=b AND t.token_hash=proof AND t.terminal_identity=terminal AND t.module='CATALOGUE'
 AND t.expires_at>clock_timestamp() AND s.enabled AND s.credential_version=t.credential_version;
 IF who IS NULL THEN RAISE EXCEPTION 'Catalogue session required' USING ERRCODE='28000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pos.admin_permissions(b,who) p WHERE p='module.catalogue') OR
 NOT EXISTS(SELECT 1 FROM pos.admin_permissions(b,who) p WHERE p='catalogue.manage') THEN
  RAISE EXCEPTION 'Catalogue edit permission required' USING ERRCODE='42501';
 END IF;
 SELECT revision INTO version FROM pos.catalogue_version WHERE branch_id=b FOR UPDATE;
 IF version IS NULL OR version<>expected THEN RAISE EXCEPTION 'Catalogue changed; reload' USING ERRCODE='23514'; END IF;
 -- Protect immutable source families and prevent destructive master removal at the write port.
 IF EXISTS(SELECT 1 FROM pos.catalogue_record r WHERE r.branch_id=b
 AND (r.source_type='branch' OR r.source_type LIKE 'special%') AND NOT EXISTS(
 SELECT 1 FROM jsonb_to_recordset(records) x(source_type text,source_id text,data jsonb)
 WHERE x.source_type=r.source_type AND x.source_id::jsonb=r.source_id::jsonb AND x.data=r.data)) THEN
  RAISE EXCEPTION 'Immutable catalogue family' USING ERRCODE='42501';
 END IF;
 IF EXISTS(SELECT 1 FROM pos.catalogue_record r WHERE r.branch_id=b
 AND r.source_type IN ('menu_item','pizza','menu_category','pizza_category','pizza_size','price_category','ingredient','burger_component','burger_recipe','modifier_group','pizza_base_option')
 AND NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(records) x(source_type text,source_id text) WHERE x.source_type=r.source_type AND x.source_id::jsonb=r.source_id::jsonb)) THEN
  RAISE EXCEPTION 'Deactivate master records instead' USING ERRCODE='23514';
 END IF;
 -- Preserve an existing working key's textual representation. Numeric JSON equality
 -- also handles Java's scientific notation without creating duplicate logical records.
 INSERT INTO pos.catalogue_record SELECT b,x.source_type,coalesce(r.source_id,x.source_id),x.data
 FROM jsonb_to_recordset(records) x(source_type text,source_id text,data jsonb)
 LEFT JOIN pos.catalogue_record r ON r.branch_id=b AND r.source_type=x.source_type AND r.source_id::jsonb=x.source_id::jsonb
 ON CONFLICT(branch_id,source_type,source_id) DO UPDATE SET data=excluded.data;
 DELETE FROM pos.catalogue_record r WHERE r.branch_id=b AND NOT EXISTS(
 SELECT 1 FROM jsonb_to_recordset(records) x(source_type text,source_id text) WHERE x.source_type=r.source_type AND x.source_id::jsonb=r.source_id::jsonb);
 INSERT INTO pos.catalog_item(item_id,branch_id,source_type,source_id,description,definition,definition_revision)
 SELECT x.item_id,b,x.source_type,x.source_id,x.description,x.definition,version+1
 FROM jsonb_to_recordset(prices) x(item_id uuid,source_type text,source_id text,description text,definition jsonb)
 ON CONFLICT(item_id) DO UPDATE SET description=excluded.description,definition=excluded.definition,definition_revision=excluded.definition_revision;
 UPDATE pos.branch_price p SET available=false,revision=revision+1 WHERE p.branch_id=b AND p.available AND NOT EXISTS(
 SELECT 1 FROM jsonb_to_recordset(prices) x(price_id uuid) WHERE x.price_id=p.price_id);
 INSERT INTO pos.branch_price(price_id,branch_id,item_id,variant_key,amount,available,revision)
 SELECT x.price_id,b,x.item_id,'baseline',x.amount,x.available,version+1
 FROM jsonb_to_recordset(prices) x(price_id uuid,item_id uuid,amount numeric,available boolean)
 ON CONFLICT(price_id) DO UPDATE SET amount=excluded.amount,available=excluded.available,revision=pos.branch_price.revision+1;
 UPDATE pos.catalogue_version SET revision=revision+1 WHERE branch_id=b RETURNING revision INTO version;
 RETURN version;
END $$;
REVOKE ALL ON FUNCTION pos.seed_catalogue_records() FROM PUBLIC;
REVOKE ALL ON FUNCTION pos.apply_catalogue_change(text,text,bigint,jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.apply_catalogue_change(text,text,bigint,jsonb,jsonb) TO pos_runtime;

REVOKE ALL ON FUNCTION pos.initialize_catalogue_records(integer,jsonb) FROM PUBLIC;
-- END V5__catalogue_management.sql

-- BEGIN V6__immutable_audit.sql
ALTER TABLE pos.module_session ADD COLUMN owner_verified_at timestamptz;

-- Additive audit storage. Legacy unknown metadata remains NULL.
ALTER TABLE pos.audit_record
 ADD COLUMN terminal_identity varchar(512), ADD COLUMN username_snapshot varchar(64),
 ADD COLUMN authorised_by_user_id uuid, ADD COLUMN entity_type varchar(64),
 ADD COLUMN transaction_id uuid, ADD COLUMN recorded_at timestamptz,
 ADD COLUMN source_system varchar(64), ADD COLUMN correlation_id uuid,
 ADD COLUMN branch_sequence bigint;
ALTER TABLE pos.audit_record ALTER COLUMN actor_id DROP NOT NULL;
CREATE INDEX audit_branch_time ON pos.audit_record(branch_id,occurred_at DESC,audit_id DESC);
CREATE INDEX audit_transaction ON pos.audit_record(branch_id,transaction_id,occurred_at DESC,audit_id DESC);
CREATE INDEX audit_actor ON pos.audit_record(branch_id,actor_id,occurred_at DESC,audit_id DESC);
CREATE INDEX audit_action ON pos.audit_record(branch_id,action,occurred_at DESC,audit_id DESC);
CREATE INDEX audit_terminal ON pos.audit_record(branch_id,terminal_identity,occurred_at DESC,audit_id DESC);
CREATE UNIQUE INDEX audit_branch_sequence ON pos.audit_record(branch_id,branch_sequence);

CREATE TABLE pos.audit_event_type(action varchar(64) PRIMARY KEY,category varchar(32) NOT NULL,optional boolean NOT NULL);
INSERT INTO pos.audit_event_type VALUES
 ('DRAFT_CREATED','Orders',true),('DRAFT_CANCELLED','Orders',true),
 ('PRICE_CHANGED','Catalogue',true),('CATALOGUE_CHANGED','Catalogue',true),
 ('STAFF_LOGIN','Staff',true),('STAFF_LOGOUT','Staff',true),
 ('CATALOGUE_BOOTSTRAPPED','System',false),('STAFF_BOOTSTRAPPED','Security',false),
 ('STAFF_CHANGED','Security',false),('ADMIN_STAFF_CHANGED','Security',false),
 ('ADMIN_ROLE_CHANGED','Security',false),('ADMIN_PIN_CHANGED','Security',false),
 ('RBAC_SET_ROLE','Security',false),('RBAC_ASSIGN_ROLES','Security',false),
 ('RBAC_SET_PIN','Security',false),('RBAC_SET_OWNER','Security',false),
 ('AUDIT_SETTING_CHANGED','Security',false),('OWNER_PIN_SUCCEEDED','Security',false),
 ('OWNER_PIN_FAILED','Security',false),('AUDIT_ACCESS_REFUSED','Security',false),('AUDIT_INTEGRITY_FAILED','Security',false);
CREATE TABLE pos.audit_policy (
 branch_id integer PRIMARY KEY REFERENCES pos.store_identity(branch_id),
 revision bigint NOT NULL DEFAULT 0, updated_at timestamptz, updated_by_owner_id uuid,
 sequence bigint NOT NULL DEFAULT 0
);
CREATE TABLE pos.audit_tracking_settings (
 branch_id integer NOT NULL REFERENCES pos.audit_policy(branch_id),
 event_type varchar(64) NOT NULL REFERENCES pos.audit_event_type(action), enabled boolean NOT NULL DEFAULT true,
 PRIMARY KEY(branch_id,event_type)
);
CREATE TABLE pos.audit_approval (
 approval_id uuid PRIMARY KEY, branch_id integer NOT NULL, initiator_hash char(64) NOT NULL,
 owner_hash char(64) NOT NULL, owner_id uuid NOT NULL, terminal_identity varchar(512) NOT NULL,
 settings jsonb NOT NULL, expected_revision bigint NOT NULL, expires_at timestamptz NOT NULL,
 consumed boolean NOT NULL DEFAULT false
);
CREATE FUNCTION pos.seed_audit_policy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pos AS $$
BEGIN
 INSERT INTO pos.audit_policy(branch_id) VALUES(NEW.branch_id);
 INSERT INTO pos.audit_tracking_settings SELECT NEW.branch_id,action,true FROM pos.audit_event_type WHERE optional;
 RETURN NEW;
END $$;
CREATE TRIGGER seed_audit_policy AFTER INSERT ON pos.store_identity FOR EACH ROW EXECUTE FUNCTION pos.seed_audit_policy();
INSERT INTO pos.audit_policy(branch_id) SELECT branch_id FROM pos.store_identity;
INSERT INTO pos.audit_tracking_settings SELECT branch_id,action,true FROM pos.store_identity CROSS JOIN pos.audit_event_type WHERE optional;

CREATE FUNCTION pos.guard_audit_history() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pos AS $$
BEGIN RAISE EXCEPTION 'Audit history is append-only' USING ERRCODE='42501'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON pos.audit_record FOR EACH STATEMENT EXECUTE FUNCTION pos.guard_audit_history();
CREATE TRIGGER immutable_audit_truncate BEFORE TRUNCATE ON pos.audit_record FOR EACH STATEMENT EXECUTE FUNCTION pos.guard_audit_history();
REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON pos.audit_record FROM pos_runtime;
GRANT SELECT ON pos.audit_event_type,pos.audit_policy,pos.audit_tracking_settings TO pos_runtime;

-- One shared ordering/policy lock with existing command processing. Outbox generation is independent.
CREATE FUNCTION pos.record_audit_event(e uuid,b integer,actor uuid,terminal text,action_value text,
 entity uuid,command uuid,details_value jsonb,approver uuid,transaction_value uuid,occurred timestamptz,source text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE n bigint; previous pos.audit_record; filtered jsonb;
BEGIN
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM pos.audit_event_type WHERE action=action_value) THEN
  RAISE EXCEPTION 'Unsupported audit action' USING ERRCODE='23514';
 END IF;
 -- Last-line defence: only explicitly safe structural fields can enter audit JSON.
 SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO filtered FROM jsonb_each(details_value)
 WHERE key IN ('orderId','state','revision','priceId','amount','available','staffId','username','enabled',
 'role','roles','name','permissions','pinConfigured','table','operation','keys','changes','subject','origin',
 'configurationRevision','oldSettings','newSettings','oldValues','newValues','tables','recordsChanged','reason','module','count','sourceDigest');
 SELECT * INTO previous FROM pos.audit_record WHERE audit_id=e;
 IF FOUND THEN
  IF previous.branch_id<>b OR previous.actor_id IS DISTINCT FROM actor OR previous.action<>action_value
    OR previous.command_id IS DISTINCT FROM command OR previous.aggregate_id<>entity
    OR previous.details<>filtered OR previous.terminal_identity IS DISTINCT FROM terminal THEN
   RAISE EXCEPTION 'Audit identity conflict' USING ERRCODE='23514';
  END IF;
  RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM pos.audit_tracking_settings WHERE branch_id=b AND event_type=action_value AND NOT enabled) THEN RETURN; END IF;
 UPDATE pos.audit_policy SET sequence=sequence+1 WHERE branch_id=b RETURNING sequence INTO n;
 INSERT INTO pos.audit_record(audit_id,branch_id,actor_id,action,aggregate_id,command_id,details,
 terminal_identity,username_snapshot,authorised_by_user_id,entity_type,transaction_id,recorded_at,source_system,correlation_id,branch_sequence,occurred_at)
 VALUES(e,b,actor,action_value,entity,command,filtered,terminal,
 (SELECT username FROM pos.staff WHERE branch_id=b AND staff_id=actor),approver,
 CASE WHEN action_value LIKE 'DRAFT_%' THEN 'ORDER' ELSE 'CONFIGURATION' END,
 transaction_value,clock_timestamp(),source,command,n,coalesce(occurred,clock_timestamp()));
END $$;

CREATE FUNCTION pos.issue_audit_approval(id uuid,initiator text,owner_proof text,terminal text,requested jsonb,expected bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE owner_id uuid; b integer;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 PERFORM pos.require_admin_session(initiator,terminal,'module.administration',false);
 owner_id=pos.require_admin_session(owner_proof,terminal,'module.administration',true);
 IF NOT EXISTS(SELECT 1 FROM pos.module_session WHERE token_hash=owner_proof AND owner_verified_at>clock_timestamp()-interval '60 seconds') THEN
  RAISE EXCEPTION 'Fresh owner PIN required' USING ERRCODE='42501';
 END IF;
 IF jsonb_typeof(requested)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(requested))<>(SELECT count(*) FROM pos.audit_event_type WHERE optional)
 OR EXISTS(SELECT 1 FROM jsonb_each(requested) v LEFT JOIN pos.audit_event_type t ON t.action=v.key
   WHERE t.action IS NULL OR NOT t.optional OR jsonb_typeof(v.value)<>'boolean') THEN
  RAISE EXCEPTION 'Invalid policy' USING ERRCODE='23514';
 END IF;
 INSERT INTO pos.audit_approval VALUES(id,b,initiator,owner_proof,owner_id,terminal,requested,expected,clock_timestamp()+interval '60 seconds',false);
END $$;

CREATE FUNCTION pos.apply_audit_policy(id uuid,initiator text,owner_proof text,terminal text,requested jsonb,expected bigint,command uuid)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE approval pos.audit_approval; actor uuid; b integer; previous jsonb; revision_value bigint; owner_id uuid;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 actor=pos.require_admin_session(initiator,terminal,'module.administration',false);
 owner_id=pos.require_admin_session(owner_proof,terminal,'module.administration',true);
 IF NOT EXISTS(SELECT 1 FROM pos.module_session WHERE token_hash=owner_proof AND owner_verified_at>clock_timestamp()-interval '60 seconds') THEN
  RAISE EXCEPTION 'Fresh owner PIN required' USING ERRCODE='42501';
 END IF;
 SELECT * INTO approval FROM pos.audit_approval WHERE approval_id=id FOR UPDATE;
 IF NOT FOUND OR approval.consumed OR approval.expires_at<=clock_timestamp()
 OR approval.branch_id<>b OR approval.initiator_hash<>initiator OR approval.owner_hash<>owner_proof
 OR approval.owner_id<>owner_id OR approval.terminal_identity<>terminal
 OR approval.settings<>requested OR approval.expected_revision<>expected THEN
  RAISE EXCEPTION 'Owner approval required' USING ERRCODE='42501';
 END IF;
 IF (SELECT revision FROM pos.audit_policy WHERE branch_id=b)<>expected THEN
  RAISE EXCEPTION 'Policy changed; reload' USING ERRCODE='23514';
 END IF;
 SELECT jsonb_object_agg(event_type,enabled) INTO previous FROM pos.audit_tracking_settings WHERE branch_id=b;
 UPDATE pos.audit_tracking_settings SET enabled=(requested->>event_type)::boolean WHERE branch_id=b;
 UPDATE pos.audit_policy SET revision=revision+1,updated_at=clock_timestamp(),updated_by_owner_id=owner_id WHERE branch_id=b RETURNING revision INTO revision_value;
 UPDATE pos.audit_approval SET consumed=true WHERE approval_id=id;
 UPDATE pos.module_session SET owner_verified_at=NULL WHERE token_hash=owner_proof;
 PERFORM pos.record_audit_event(id,b,actor,terminal,'OWNER_PIN_SUCCEEDED',command,command,
 jsonb_build_object('configurationRevision',revision_value),owner_id,NULL,NULL,'LOCAL_MASTER');
 PERFORM pos.record_audit_event(command,b,actor,terminal,'AUDIT_SETTING_CHANGED',command,command,
 jsonb_build_object('oldSettings',previous,'newSettings',requested,'configurationRevision',revision_value),owner_id,NULL,NULL,'LOCAL_MASTER');
 RETURN revision_value;
END $$;
REVOKE ALL ON FUNCTION pos.seed_audit_policy(),pos.guard_audit_history(),pos.record_audit_event(uuid,integer,uuid,text,text,uuid,uuid,jsonb,uuid,uuid,timestamptz,text),
 pos.issue_audit_approval(uuid,text,text,text,jsonb,bigint),pos.apply_audit_policy(uuid,text,text,text,jsonb,bigint,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.record_audit_event(uuid,integer,uuid,text,text,uuid,uuid,jsonb,uuid,uuid,timestamptz,text),
 pos.issue_audit_approval(uuid,text,text,text,jsonb,bigint),pos.apply_audit_policy(uuid,text,text,text,jsonb,bigint,uuid) TO pos_runtime;
-- END V6__immutable_audit.sql

-- BEGIN V7__audit_identity_guards.sql
-- Preserve V6 checksums; strengthen replay identity and mandatory-event guarantees additively.
ALTER TABLE pos.audit_tracking_settings ADD CONSTRAINT optional_audit_types_only
 CHECK (event_type IN ('DRAFT_CREATED','DRAFT_CANCELLED','PRICE_CHANGED','CATALOGUE_CHANGED','STAFF_LOGIN','STAFF_LOGOUT'));

CREATE OR REPLACE FUNCTION pos.record_audit_event(e uuid,b integer,actor uuid,terminal text,action_value text,
 entity uuid,command uuid,details_value jsonb,approver uuid,transaction_value uuid,occurred timestamptz,source text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE n bigint; previous pos.audit_record; filtered jsonb;
BEGIN
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM pos.audit_event_type WHERE action=action_value) THEN
  RAISE EXCEPTION 'Unsupported audit action' USING ERRCODE='23514';
 END IF;
 -- Last-line defence: only explicitly safe structural fields can enter audit JSON.
 SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO filtered FROM jsonb_each(details_value)
 WHERE key IN ('orderId','state','revision','priceId','amount','available','staffId','username','enabled',
 'role','roles','name','permissions','pinConfigured','table','operation','keys','changes','subject','origin',
 'configurationRevision','oldSettings','newSettings','oldValues','newValues','tables','recordsChanged','reason','module','count','sourceDigest');
 SELECT * INTO previous FROM pos.audit_record WHERE audit_id=e;
 IF FOUND THEN
  IF previous.branch_id<>b OR previous.actor_id IS DISTINCT FROM actor OR previous.action<>action_value
    OR previous.command_id IS DISTINCT FROM command OR previous.aggregate_id<>entity
    OR previous.details<>filtered OR previous.terminal_identity IS DISTINCT FROM terminal
    OR previous.authorised_by_user_id IS DISTINCT FROM approver OR previous.transaction_id IS DISTINCT FROM transaction_value
    OR previous.source_system IS DISTINCT FROM source
    OR (occurred IS NOT NULL AND previous.occurred_at IS DISTINCT FROM occurred) THEN
   RAISE EXCEPTION 'Audit identity conflict' USING ERRCODE='23514';
  END IF;
  RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM pos.audit_tracking_settings s JOIN pos.audit_event_type t ON t.action=s.event_type WHERE s.branch_id=b AND s.event_type=action_value AND t.optional AND NOT s.enabled) THEN RETURN; END IF;
 UPDATE pos.audit_policy SET sequence=sequence+1 WHERE branch_id=b RETURNING sequence INTO n;
 INSERT INTO pos.audit_record(audit_id,branch_id,actor_id,action,aggregate_id,command_id,details,
 terminal_identity,username_snapshot,authorised_by_user_id,entity_type,transaction_id,recorded_at,source_system,correlation_id,branch_sequence,occurred_at)
 VALUES(e,b,actor,action_value,entity,command,filtered,terminal,
 (SELECT username FROM pos.staff WHERE branch_id=b AND staff_id=actor),approver,
 CASE WHEN action_value LIKE 'DRAFT_%' THEN 'ORDER' ELSE 'CONFIGURATION' END,
 transaction_value,clock_timestamp(),source,command,n,coalesce(occurred,clock_timestamp()));
END $$;
-- END V7__audit_identity_guards.sql

-- BEGIN V8__developer_recovery.sql
-- No default credential, no staff account, no runtime access to the verifier.
CREATE TABLE pos.developer_recovery (
 branch_id integer PRIMARY KEY REFERENCES pos.store_identity(branch_id),
 installation_id uuid NOT NULL,
 cluster_id uuid NOT NULL,
 verifier text NOT NULL,
 enabled boolean NOT NULL DEFAULT false,
 changed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
REVOKE ALL ON pos.developer_recovery FROM PUBLIC,pos_runtime;
INSERT INTO pos.audit_event_type(action,category,optional) VALUES
 ('DEVELOPER_RECOVERY_ENROLLED','Security',false),
 ('DEVELOPER_RECOVERY_ROTATED','Security',false),
 ('DEVELOPER_RECOVERY_DISABLED','Security',false),
 ('DEVELOPER_RECOVERY_FAILED','Security',false),
 ('OWNER_PIN_RECOVERED','Security',false);

CREATE FUNCTION pos.developer_recovery_status(proof text,terminal text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer; result jsonb;
BEGIN
 PERFORM pos.require_admin_session(proof,terminal,'module.administration',true);
 SELECT branch_id INTO b FROM pos.module_session WHERE token_hash=proof;
 SELECT jsonb_build_object('configured',true,'enabled',r.enabled,'changedAt',r.changed_at) INTO result
 FROM pos.developer_recovery r JOIN pos.store_identity s USING(branch_id)
 WHERE r.branch_id=b AND r.installation_id=s.installation_id AND r.cluster_id=s.cluster_id;
 RETURN coalesce(result,jsonb_build_object('configured',false,'enabled',false));
END $$;
CREATE FUNCTION pos.disable_developer_recovery(proof text,terminal text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer; actor uuid; installation uuid;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 actor=pos.require_admin_session(proof,terminal,'module.administration',true);
 SELECT installation_id INTO installation FROM pos.store_identity WHERE branch_id=b;
 UPDATE pos.developer_recovery SET enabled=false,changed_at=clock_timestamp() WHERE branch_id=b;
 PERFORM pos.record_audit_event(gen_random_uuid(),b,actor,terminal,'DEVELOPER_RECOVERY_DISABLED',installation,NULL,
   '{"origin":"owner-system-access"}'::jsonb,NULL,NULL,NULL,'LOCAL_MASTER');
END $$;
REVOKE ALL ON FUNCTION pos.developer_recovery_status(text,text),pos.disable_developer_recovery(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.developer_recovery_status(text,text),pos.disable_developer_recovery(text,text) TO pos_runtime;
-- END V8__developer_recovery.sql

-- BEGIN V9__persistent_customers.sql
-- Extend the existing UUID customer authority; preserve all legacy rows and draft references.
ALTER TABLE pos.local_customer ALTER COLUMN display_name TYPE varchar(511);
ALTER TABLE pos.local_customer ADD COLUMN profile jsonb NOT NULL DEFAULT '{}',
 ADD COLUMN field_times jsonb NOT NULL DEFAULT '{}', ADD COLUMN normalized_phone varchar(16),
 ADD COLUMN normalized_email varchar(255), ADD COLUMN preferred_branch integer,
 ADD COLUMN archived boolean NOT NULL DEFAULT false, ADD COLUMN banned boolean NOT NULL DEFAULT false,
 ADD COLUMN ban_reason varchar(2000) NOT NULL DEFAULT '', ADD COLUMN ban_changed_at timestamptz,
 ADD COLUMN global_id uuid, ADD COLUMN cloud_id bigint, ADD COLUMN canonical_customer_id uuid,
 ADD COLUMN sync_state varchar(32) NOT NULL DEFAULT 'PENDING', ADD COLUMN updated_at timestamptz;
UPDATE pos.local_customer SET profile=jsonb_build_object('first_name',display_name,'last_name','','phone1',coalesce(phone,''),'phone2','','email','','formatted_address',coalesce(address,''),'preferred_store',CASE branch_id WHEN 1 THEN 'Kenridge' ELSE 'Uitzicht' END),preferred_branch=branch_id,global_id=customer_id;
ALTER TABLE pos.local_customer ADD CONSTRAINT customer_alias_fk FOREIGN KEY(branch_id,canonical_customer_id) REFERENCES pos.local_customer(branch_id,customer_id);
CREATE UNIQUE INDEX customer_phone_unique ON pos.local_customer(branch_id,normalized_phone) WHERE normalized_phone IS NOT NULL AND canonical_customer_id IS NULL;
CREATE UNIQUE INDEX customer_email_unique ON pos.local_customer(branch_id,normalized_email) WHERE normalized_email IS NOT NULL AND canonical_customer_id IS NULL;
CREATE UNIQUE INDEX customer_cloud_unique ON pos.local_customer(branch_id,cloud_id) WHERE cloud_id IS NOT NULL AND canonical_customer_id IS NULL;
CREATE INDEX customer_directory ON pos.local_customer(branch_id,archived,preferred_branch,lower(display_name),customer_id);
ALTER TABLE pos.order_draft ADD COLUMN customer_snapshot jsonb;
CREATE INDEX customer_drafts ON pos.order_draft(branch_id,customer_id,created_at DESC,sync_id);
CREATE TABLE pos.customer_status_history(
 event_id uuid PRIMARY KEY,branch_id integer NOT NULL,customer_id uuid NOT NULL,
 action varchar(64) NOT NULL,actor_id uuid,terminal_identity varchar(512),reason varchar(2000) NOT NULL DEFAULT '',
 occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),command_id uuid NOT NULL UNIQUE,
 FOREIGN KEY(branch_id,customer_id) REFERENCES pos.local_customer(branch_id,customer_id)
);
CREATE TABLE pos.customer_alias(
 alias_id uuid PRIMARY KEY,branch_id integer NOT NULL,customer_id uuid NOT NULL,
 FOREIGN KEY(branch_id,customer_id) REFERENCES pos.local_customer(branch_id,customer_id)
);
CREATE TABLE pos.customer_conflict(
 conflict_id uuid PRIMARY KEY,branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
 source_event uuid NOT NULL UNIQUE,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,
 reason varchar(128) NOT NULL,state varchar(16) NOT NULL DEFAULT 'OPEN',revision bigint NOT NULL DEFAULT 0,
 resolution jsonb,resolved_by uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),resolved_at timestamptz
);
CREATE TABLE pos.customer_sync_pending(
 event_id uuid PRIMARY KEY REFERENCES pos.outbox_event(event_id),branch_id integer NOT NULL,
 customer_id uuid NOT NULL,state varchar(32) NOT NULL DEFAULT 'PENDING',acknowledged_at timestamptz,ack_reference text,ack_global uuid,ack_cloud bigint,
 FOREIGN KEY(branch_id,customer_id) REFERENCES pos.local_customer(branch_id,customer_id)
);
CREATE INDEX customer_conflicts_open ON pos.customer_conflict(branch_id,state,created_at,conflict_id);
-- Normalize only recognizable legacy contacts. Collisions retain every UUID and become
-- explicit conflicts; no historical timestamp or identity is invented.
DO $$ DECLARE r record; cleaned text; normal text; matches jsonb; BEGIN
 FOR r IN SELECT customer_id,branch_id,phone FROM pos.local_customer LOOP
  cleaned=regexp_replace(coalesce(r.phone,''),'[[:space:]().-]','','g');
  IF cleaned ~ '^00' THEN cleaned='+'||substring(cleaned FROM 3); END IF;
  IF cleaned ~ '^0[0-9]{9}$' THEN cleaned='+27'||substring(cleaned FROM 2); END IF;
  IF cleaned ~ '^\+[1-9][0-9]{7,14}$' THEN
   UPDATE pos.local_customer SET profile=jsonb_set(profile,'{phone1}',to_jsonb(cleaned)) WHERE customer_id=r.customer_id;
  END IF;
 END LOOP;
 FOR r IN SELECT branch_id,profile->>'phone1' AS phone,jsonb_agg(customer_id ORDER BY customer_id) AS ids,count(*) AS total FROM pos.local_customer WHERE profile->>'phone1' ~ '^\+[1-9][0-9]{7,14}$' GROUP BY branch_id,profile->>'phone1' LOOP
  IF r.total=1 THEN UPDATE pos.local_customer SET normalized_phone=r.phone WHERE customer_id=(r.ids->>0)::uuid;
  ELSE
   INSERT INTO pos.customer_conflict(conflict_id,branch_id,source_event,payload_hash,payload,reason)
   SELECT customer_id,branch_id,customer_id,repeat('0',64),jsonb_build_object('proposedId',customer_id,'proposedRevision',revision,'fields',profile,'matches',r.ids),'LEGACY_CONTACT_COLLISION' FROM pos.local_customer WHERE branch_id=r.branch_id AND profile->>'phone1'=r.phone;
   UPDATE pos.local_customer SET sync_state='CONFLICT' WHERE branch_id=r.branch_id AND profile->>'phone1'=r.phone;
  END IF;
 END LOOP;
END $$;
REVOKE INSERT,UPDATE ON pos.local_customer FROM pos_runtime;
GRANT SELECT ON pos.customer_status_history,pos.customer_alias,pos.customer_conflict,pos.customer_sync_pending TO pos_runtime;

-- Explicit action permissions, additive to existing module entry permissions.
INSERT INTO pos.role_permission SELECT branch_id,name,p FROM pos.rbac_role CROSS JOIN unnest(ARRAY['customers.view','customers.manage','customers.archive','customers.ban','customers.resolve']) p WHERE name='MANAGER' ON CONFLICT DO NOTHING;
-- Existing administration functions validate their allowlist. Extend it without changing prior migration checksums.
DO $$ DECLARE body text; BEGIN
 SELECT pg_get_functiondef('pos.apply_admin_change(text,text,text,jsonb)'::regprocedure) INTO body;
 body=replace(body,'''audit.view'',''catalogue.manage''','''audit.view'',''catalogue.manage'',''customers.view'',''customers.manage'',''customers.archive'',''customers.ban'',''customers.resolve''');
 EXECUTE body;
END $$;
CREATE FUNCTION pos.require_customer_session(proof text,terminal text,permission_value text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE who uuid;b integer;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 SELECT t.staff_id INTO who FROM pos.module_session t JOIN pos.staff s ON s.branch_id=t.branch_id AND s.staff_id=t.staff_id
 WHERE t.token_hash=proof AND t.branch_id=b AND t.terminal_identity=terminal AND t.module='CUSTOMERS'
 AND t.expires_at>clock_timestamp() AND s.enabled AND s.credential_version=t.credential_version;
 IF who IS NULL THEN RAISE EXCEPTION 'Customers session required' USING ERRCODE='28000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pos.staff_role r JOIN pos.role_permission p ON p.branch_id=r.branch_id AND p.role_name=r.role_name
 WHERE r.branch_id=b AND r.staff_id=who AND p.permission=permission_value) THEN
  RAISE EXCEPTION 'Customer permission required' USING ERRCODE='42501'; END IF;
 RETURN who;
END $$;
CREATE FUNCTION pos.write_customer(proof text,terminal text,id uuid,expected bigint,operation text,data jsonb,command uuid)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;who uuid;previous pos.local_customer;next_revision bigint;stamp timestamptz;profile_value jsonb;name_value text;target pos.local_customer;k text;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 who=pos.require_customer_session(proof,terminal,CASE operation WHEN 'ARCHIVE' THEN 'customers.archive' WHEN 'BAN' THEN 'customers.ban' WHEN 'LINK' THEN 'customers.resolve' WHEN 'RESOLVE_SAVE' THEN 'customers.resolve' ELSE 'customers.manage' END);
 SELECT * INTO previous FROM pos.local_customer WHERE branch_id=b AND customer_id=id FOR UPDATE;
 IF operation IN ('SAVE','RESOLVE_SAVE') AND expected=-1 AND NOT FOUND THEN NULL;
 ELSIF NOT FOUND OR previous.revision<>expected OR previous.canonical_customer_id IS NOT NULL THEN
  RAISE EXCEPTION 'Customer changed; reload' USING ERRCODE='23514';
 END IF;
 IF EXISTS(SELECT 1 FROM pos.customer_alias WHERE alias_id=id AND customer_id<>id) THEN RAISE EXCEPTION 'Customer identity is already linked' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM pos.local_customer WHERE customer_id=id AND branch_id<>b) THEN RAISE EXCEPTION 'Foreign customer' USING ERRCODE='42501'; END IF;
 stamp=clock_timestamp();next_revision=coalesce(previous.revision+1,0);
 IF operation IN ('SAVE','RESOLVE_SAVE') THEN
  profile_value=data;
  IF jsonb_typeof(data)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each(data) v WHERE jsonb_typeof(value)<>'string' OR key NOT IN
   ('first_name','last_name','phone1','phone2','email','house_number','street','area','complex_name','preferred_store','city','postal_code','google_place_id','formatted_address','latitude','longitude','province','country')) THEN
   RAISE EXCEPTION 'Invalid profile fields' USING ERRCODE='23514'; END IF;
  name_value=btrim(coalesce(data->>'first_name','')||' '||coalesce(data->>'last_name',''));
  IF name_value='' OR coalesce(data->>'phone1','') !~ '^\+[1-9][0-9]{7,14}$' OR length(data->>'phone1')>20
   OR length(coalesce(data->>'email',''))>255 THEN RAISE EXCEPTION 'Invalid name or phone' USING ERRCODE='23514'; END IF;
  IF data->>'preferred_store' IS DISTINCT FROM coalesce(previous.profile->>'preferred_store',CASE b WHEN 1 THEN 'Kenridge' ELSE 'Uitzicht' END) THEN
   RAISE EXCEPTION 'Only the customer changes preferred store' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM pos.local_customer WHERE branch_id=b AND customer_id<>id AND canonical_customer_id IS NULL AND profile->>'phone1'=data->>'phone1') THEN RAISE EXCEPTION 'Contact collision' USING ERRCODE='23505'; END IF;
  INSERT INTO pos.local_customer(customer_id,branch_id,display_name,phone,address,profile,normalized_phone,normalized_email,preferred_branch,global_id,revision,updated_at)
  VALUES(id,b,name_value,data->>'phone1',data->>'formatted_address',data,data->>'phone1',nullif(lower(btrim(data->>'email')),''),b,id,0,stamp)
  ON CONFLICT(customer_id) DO UPDATE SET display_name=excluded.display_name,phone=excluded.phone,address=excluded.address,
   profile=excluded.profile,normalized_phone=excluded.normalized_phone,normalized_email=excluded.normalized_email,revision=next_revision,updated_at=stamp,sync_state='PENDING';
  IF previous.profile IS NULL THEN UPDATE pos.local_customer SET field_times=jsonb_set(field_times,'{preferred_store}',to_jsonb(stamp)) WHERE customer_id=id; END IF;
  -- Address is one atomic timestamped group; other contact fields are individually versioned.
  FOR k IN SELECT key FROM jsonb_each(data) WHERE key NOT IN ('preferred_store','house_number','street','area','complex_name','city','postal_code','google_place_id','formatted_address','latitude','longitude','province','country') LOOP
   IF previous.profile->k IS DISTINCT FROM data->k THEN UPDATE pos.local_customer SET field_times=jsonb_set(field_times,ARRAY[k],to_jsonb(stamp)) WHERE customer_id=id; END IF;
  END LOOP;
  IF previous.profile IS NULL OR (previous.profile-ARRAY['first_name','last_name','phone1','phone2','email','preferred_store']) IS DISTINCT FROM (data-ARRAY['first_name','last_name','phone1','phone2','email','preferred_store']) THEN
   UPDATE pos.local_customer SET field_times=jsonb_set(field_times,'{address}',to_jsonb(stamp)) WHERE customer_id=id;
  END IF;
 ELSIF operation='ARCHIVE' THEN
  UPDATE pos.local_customer SET archived=(data->>'value')::boolean,revision=next_revision,updated_at=stamp WHERE customer_id=id;
 ELSIF operation='BAN' THEN
  IF coalesce((data->>'value')::boolean,true) AND length(btrim(coalesce(data->>'reason','')))=0 THEN RAISE EXCEPTION 'Ban reason required' USING ERRCODE='23514'; END IF;
  IF length(coalesce(data->>'reason',''))>2000 THEN RAISE EXCEPTION 'Reason too long' USING ERRCODE='23514'; END IF;
  UPDATE pos.local_customer SET banned=(data->>'value')::boolean,ban_reason=CASE WHEN (data->>'value')::boolean THEN data->>'reason' ELSE '' END,
    ban_changed_at=stamp,field_times=jsonb_set(field_times,'{ban}',to_jsonb(stamp)),revision=next_revision,updated_at=stamp,sync_state='PENDING' WHERE customer_id=id;
 ELSIF operation='LINK' THEN
  SELECT * INTO target FROM pos.local_customer WHERE branch_id=b AND customer_id=(data->>'target')::uuid AND canonical_customer_id IS NULL FOR UPDATE;
  IF NOT FOUND OR target.customer_id=id THEN RAISE EXCEPTION 'Invalid link target' USING ERRCODE='23514'; END IF;
  UPDATE pos.local_customer SET canonical_customer_id=target.customer_id,normalized_phone=NULL,normalized_email=NULL,revision=next_revision,updated_at=stamp WHERE customer_id=id;
  INSERT INTO pos.customer_alias VALUES(id,b,target.customer_id) ON CONFLICT(alias_id) DO UPDATE SET customer_id=excluded.customer_id;
  UPDATE pos.customer_alias SET customer_id=target.customer_id WHERE branch_id=b AND customer_id=id;
  UPDATE pos.local_customer SET canonical_customer_id=target.customer_id WHERE branch_id=b AND canonical_customer_id=id;
  IF previous.banned AND NOT target.banned THEN UPDATE pos.local_customer SET banned=true,ban_reason=previous.ban_reason,ban_changed_at=stamp,field_times=jsonb_set(field_times,'{ban}',to_jsonb(stamp)),revision=revision+1,sync_state='PENDING' WHERE customer_id=target.customer_id; END IF;
 ELSE RAISE EXCEPTION 'Unsupported customer operation' USING ERRCODE='23514';
 END IF;
 INSERT INTO pos.customer_status_history VALUES(command,b,id,operation,who,terminal,CASE WHEN operation='BAN' THEN coalesce(data->>'reason','') ELSE '' END,stamp,command);
 RETURN next_revision;
END $$;
CREATE FUNCTION pos.queue_customer_sync(event uuid,b integer,id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pos.outbox_event WHERE event_id=event AND branch_id=b AND event_type LIKE 'CUSTOMER_%') THEN RAISE EXCEPTION 'Customer outbox required' USING ERRCODE='23514'; END IF;
 INSERT INTO pos.customer_sync_pending(event_id,branch_id,customer_id) VALUES(event,b,id) ON CONFLICT DO NOTHING;
END $$;
CREATE FUNCTION pos.customer_conflict_write(proof text,terminal text,id uuid,source uuid,digest text,payload_value jsonb,reason_value text,expected bigint,resolution_value jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;who uuid;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 who=pos.require_customer_session(proof,terminal,CASE WHEN expected<0 THEN 'customers.manage' ELSE 'customers.resolve' END);
 IF expected<0 THEN
  INSERT INTO pos.customer_conflict(conflict_id,branch_id,source_event,payload_hash,payload,reason) VALUES(id,b,source,digest,payload_value,reason_value)
  ON CONFLICT(source_event) DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM pos.customer_conflict WHERE source_event=source AND payload_hash=digest) THEN RAISE EXCEPTION 'Conflict source changed' USING ERRCODE='23514'; END IF;
 ELSE
  UPDATE pos.customer_conflict SET state='RESOLVED',revision=revision+1,resolution=resolution_value,resolved_by=who,resolved_at=clock_timestamp()
  WHERE conflict_id=id AND branch_id=b AND revision=expected AND state='OPEN';
  IF NOT FOUND THEN RAISE EXCEPTION 'Conflict changed' USING ERRCODE='23514'; END IF;
 END IF;
END $$;
REVOKE ALL ON FUNCTION pos.require_customer_session(text,text,text),pos.write_customer(text,text,uuid,bigint,text,jsonb,uuid),pos.queue_customer_sync(uuid,integer,uuid),pos.customer_conflict_write(text,text,uuid,uuid,text,jsonb,text,bigint,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.require_customer_session(text,text,text),pos.write_customer(text,text,uuid,bigint,text,jsonb,uuid),pos.queue_customer_sync(uuid,integer,uuid),pos.customer_conflict_write(text,text,uuid,uuid,text,jsonb,text,bigint,jsonb) TO pos_runtime;
-- Customer lifecycle tracking is optional; bans, unbans, links and remote identity application are mandatory.
INSERT INTO pos.audit_event_type VALUES
 ('CUSTOMER_CREATED','Customers',true),('CUSTOMER_UPDATED','Customers',true),('CUSTOMER_ARCHIVED','Customers',true),('CUSTOMER_RESTORED','Customers',true),
 ('CUSTOMER_BANNED','Security',false),('CUSTOMER_UNBANNED','Security',false),('CUSTOMER_CONFLICT_RESOLVED','Security',false),('CUSTOMER_SYNC_APPLIED','Customers',false);
ALTER TABLE pos.audit_tracking_settings DROP CONSTRAINT optional_audit_types_only;
ALTER TABLE pos.audit_tracking_settings ADD CONSTRAINT optional_audit_types_only CHECK(event_type IN ('DRAFT_CREATED','DRAFT_CANCELLED','PRICE_CHANGED','CATALOGUE_CHANGED','STAFF_LOGIN','STAFF_LOGOUT','CUSTOMER_CREATED','CUSTOMER_UPDATED','CUSTOMER_ARCHIVED','CUSTOMER_RESTORED'));
INSERT INTO pos.audit_tracking_settings SELECT branch_id,action,true FROM pos.audit_policy CROSS JOIN pos.audit_event_type WHERE optional ON CONFLICT DO NOTHING;
CREATE FUNCTION pos.resolve_customer_identity(proof text,terminal text,source uuid,target_id uuid,command uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;who uuid;existing pos.local_customer;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 who=pos.require_customer_session(proof,terminal,'customers.resolve');
 IF NOT EXISTS(SELECT 1 FROM pos.local_customer WHERE branch_id=b AND customer_id=target_id AND canonical_customer_id IS NULL) OR source=target_id THEN RAISE EXCEPTION 'Invalid link target' USING ERRCODE='23514'; END IF;
 SELECT * INTO existing FROM pos.local_customer WHERE branch_id=b AND customer_id=source;
 IF FOUND THEN PERFORM pos.write_customer(proof,terminal,source,existing.revision,'LINK',jsonb_build_object('target',target_id),command);
 ELSE
  IF EXISTS(SELECT 1 FROM pos.customer_alias WHERE alias_id=source AND (branch_id<>b OR customer_id<>target_id)) THEN RAISE EXCEPTION 'Alias conflict' USING ERRCODE='23514'; END IF;
  INSERT INTO pos.customer_alias VALUES(source,b,target_id) ON CONFLICT DO NOTHING;
  INSERT INTO pos.customer_status_history VALUES(command,b,target_id,'LINK',who,terminal,'',clock_timestamp(),command);
 END IF;
 UPDATE pos.local_customer SET sync_state='PENDING' WHERE branch_id=b AND customer_id=target_id;
END $$;
CREATE FUNCTION pos.guard_customer_draft() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE customer pos.local_customer;
BEGIN
 IF TG_OP='UPDATE' AND OLD.customer_id IS NOT NULL AND NEW.customer_id IS DISTINCT FROM OLD.customer_id THEN RAISE EXCEPTION 'Historical customer linkage is immutable' USING ERRCODE='42501'; END IF;
 IF NEW.customer_id IS NULL THEN
  IF NEW.customer_snapshot IS NOT NULL THEN RAISE EXCEPTION 'Anonymous draft has no customer snapshot' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND NEW.customer_id IS NOT DISTINCT FROM OLD.customer_id THEN
  IF NEW.customer_snapshot IS DISTINCT FROM OLD.customer_snapshot THEN RAISE EXCEPTION 'Historical customer snapshot is immutable' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 PERFORM position FROM pos.stream_head WHERE branch_id=NEW.branch_id FOR UPDATE;
 SELECT * INTO customer FROM pos.local_customer WHERE branch_id=NEW.branch_id AND customer_id=coalesce((SELECT customer_id FROM pos.customer_alias WHERE branch_id=NEW.branch_id AND alias_id=NEW.customer_id),NEW.customer_id);
 IF NOT FOUND OR customer.banned OR customer.archived OR customer.canonical_customer_id IS NOT NULL THEN RAISE EXCEPTION 'Customer unavailable for new orders' USING ERRCODE='23514'; END IF;
 NEW.customer_id=customer.customer_id;
 NEW.customer_snapshot=jsonb_build_object('customerId',customer.customer_id,'name',customer.display_name,'profile',customer.profile);
 RETURN NEW;
END $$;
CREATE TRIGGER customer_draft_guard BEFORE INSERT OR UPDATE OF customer_id,customer_snapshot ON pos.order_draft FOR EACH ROW EXECUTE FUNCTION pos.guard_customer_draft();
CREATE FUNCTION pos.customer_role_defaults() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pos AS $$
BEGIN
 IF NEW.name='MANAGER' THEN INSERT INTO pos.role_permission SELECT NEW.branch_id,NEW.name,p FROM unnest(ARRAY['customers.view','customers.manage','customers.archive','customers.ban','customers.resolve']) p ON CONFLICT DO NOTHING; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER customer_role_defaults AFTER INSERT ON pos.rbac_role FOR EACH ROW EXECUTE FUNCTION pos.customer_role_defaults();
REVOKE ALL ON FUNCTION pos.resolve_customer_identity(text,text,uuid,uuid,uuid),pos.guard_customer_draft(),pos.customer_role_defaults() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.resolve_customer_identity(text,text,uuid,uuid,uuid) TO pos_runtime;
-- Extend the central safe-detail allowlist, retaining all existing recorder protections.
DO $$ DECLARE body text; BEGIN
 SELECT pg_get_functiondef('pos.record_audit_event(uuid,integer,uuid,text,text,uuid,uuid,jsonb,uuid,uuid,timestamptz,text)'::regprocedure) INTO body;
 body=replace(body,'''sourceDigest''','''sourceDigest'',''customerId'',''fields''');EXECUTE body;
END $$;
CREATE UNIQUE INDEX customer_global_unique ON pos.local_customer(branch_id,global_id) WHERE canonical_customer_id IS NULL;
-- Staged sync ports require an authorised resolver session. No HTTP route or worker invokes them.
CREATE FUNCTION pos.apply_customer_remote(proof text,terminal text,id uuid,data jsonb,event uuid,digest text,result_value jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;who uuid;previous pos.local_customer;normalized text;email_value text;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 who=pos.require_customer_session(proof,terminal,'customers.resolve');
 IF EXISTS(SELECT 1 FROM pos.inbox_receipt WHERE event_id=event AND payload_hash<>digest) THEN RAISE EXCEPTION 'Remote event conflict' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM pos.inbox_receipt WHERE event_id=event) THEN RETURN; END IF;
 IF data IS NOT NULL THEN
  normalized=data->'fields'->>'phone1';email_value=nullif(lower(data->'fields'->>'email'),'');
  IF normalized !~ '^\+[1-9][0-9]{7,14}$' OR (data->>'preferredBranch')::integer NOT IN (1,2) OR NOT data ? 'fieldTimes' THEN RAISE EXCEPTION 'Invalid remote profile' USING ERRCODE='23514'; END IF;
  SELECT * INTO previous FROM pos.local_customer WHERE customer_id=id AND branch_id=b;
  IF EXISTS(SELECT 1 FROM pos.local_customer WHERE customer_id=id AND branch_id<>b) THEN RAISE EXCEPTION 'Foreign customer' USING ERRCODE='42501'; END IF;
  INSERT INTO pos.local_customer(customer_id,branch_id,display_name,phone,address,profile,field_times,normalized_phone,normalized_email,preferred_branch,banned,ban_reason,ban_changed_at,global_id,cloud_id,revision,updated_at,sync_state)
  VALUES(id,b,btrim((data->'fields'->>'first_name')||' '||(data->'fields'->>'last_name')),normalized,data->'fields'->>'formatted_address',data->'fields',data->'fieldTimes',normalized,email_value,(data->>'preferredBranch')::integer,
   (data->>'banned')::boolean,coalesce(data->>'banReason',''),(data->>'banChangedAt')::timestamptz,(data->>'globalId')::uuid,(data->>'cloudId')::bigint,0,clock_timestamp(),'SYNCED')
  ON CONFLICT(customer_id) DO UPDATE SET display_name=excluded.display_name,phone=excluded.phone,address=excluded.address,profile=excluded.profile,field_times=excluded.field_times,
   normalized_phone=excluded.normalized_phone,normalized_email=excluded.normalized_email,preferred_branch=excluded.preferred_branch,banned=excluded.banned,ban_reason=excluded.ban_reason,ban_changed_at=excluded.ban_changed_at,
   global_id=excluded.global_id,cloud_id=excluded.cloud_id,revision=pos.local_customer.revision+1,updated_at=excluded.updated_at,
   sync_state=CASE WHEN EXISTS(SELECT 1 FROM pos.customer_sync_pending WHERE customer_id=id AND state='PENDING') THEN 'PENDING' ELSE 'SYNCED' END;
  IF (data->>'globalId')::uuid<>id THEN INSERT INTO pos.customer_alias VALUES((data->>'globalId')::uuid,b,id) ON CONFLICT(alias_id) DO NOTHING; END IF;
  IF (previous.customer_id IS NOT NULL AND (previous.banned IS DISTINCT FROM (data->>'banned')::boolean OR previous.ban_reason IS DISTINCT FROM coalesce(data->>'banReason',''))) OR (previous.customer_id IS NULL AND (data->>'banned')::boolean) THEN
   INSERT INTO pos.customer_status_history VALUES(event,b,id,CASE WHEN (data->>'banned')::boolean THEN 'REMOTE_BAN' ELSE 'REMOTE_UNBAN' END,NULL,NULL,coalesce(data->>'banReason',''),(data->>'banChangedAt')::timestamptz,event);
  END IF;
  PERFORM pos.record_audit_event(event,b,who,terminal,'CUSTOMER_SYNC_APPLIED',id,NULL,jsonb_build_object('customerId',id),NULL,NULL,NULL,'CLOUD');
 END IF;
 INSERT INTO pos.inbox_receipt(event_id,branch_id,payload_hash,result) VALUES(event,b,digest,result_value);
END $$;
CREATE FUNCTION pos.ack_customer_sync(proof text,terminal text,event uuid,digest text,ack text,global_value uuid,cloud_value bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;who uuid;target uuid;existing pos.local_customer;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;who=pos.require_customer_session(proof,terminal,'customers.resolve');
 IF length(coalesce(ack,''))=0 OR NOT EXISTS(SELECT 1 FROM pos.outbox_event WHERE event_id=event AND branch_id=b AND encode(sha256(convert_to(payload::text,'UTF8')),'hex')=digest) THEN RAISE EXCEPTION 'Acknowledgement mismatch' USING ERRCODE='23514'; END IF;
 SELECT customer_id INTO target FROM pos.customer_sync_pending WHERE event_id=event AND branch_id=b AND state='PENDING' FOR UPDATE;
 IF NOT FOUND THEN
  IF NOT EXISTS(SELECT 1 FROM pos.customer_sync_pending WHERE event_id=event AND branch_id=b AND ack_reference=ack AND ack_global IS NOT DISTINCT FROM global_value AND ack_cloud IS NOT DISTINCT FROM cloud_value) THEN RAISE EXCEPTION 'Acknowledgement replay conflict' USING ERRCODE='23514'; END IF;
  RETURN;
 END IF;
 SELECT * INTO existing FROM pos.local_customer WHERE branch_id=b AND customer_id=coalesce((SELECT customer_id FROM pos.customer_alias WHERE alias_id=target AND branch_id=b),target);
 IF existing.global_id IS DISTINCT FROM coalesce(global_value,existing.global_id) OR existing.cloud_id IS DISTINCT FROM coalesce(cloud_value,existing.cloud_id) THEN
  PERFORM pos.record_audit_event(md5(event::text||':ack')::uuid,b,who,terminal,'CUSTOMER_SYNC_APPLIED',existing.customer_id,NULL,jsonb_build_object('customerId',existing.customer_id),NULL,NULL,NULL,'CLOUD');
 END IF;
 UPDATE pos.customer_sync_pending SET state='ACKNOWLEDGED',acknowledged_at=clock_timestamp(),ack_reference=ack,ack_global=global_value,ack_cloud=cloud_value WHERE event_id=event;
 UPDATE pos.local_customer SET global_id=coalesce(global_value,global_id),cloud_id=coalesce(cloud_value,cloud_id),
 sync_state=CASE WHEN EXISTS(SELECT 1 FROM pos.customer_sync_pending p WHERE p.branch_id=b AND p.state='PENDING' AND (p.customer_id=existing.customer_id OR p.customer_id IN (SELECT alias_id FROM pos.customer_alias WHERE customer_id=existing.customer_id AND branch_id=b))) THEN 'PENDING' ELSE 'SYNCED' END WHERE customer_id=existing.customer_id;
END $$;
REVOKE ALL ON FUNCTION pos.apply_customer_remote(text,text,uuid,jsonb,uuid,text,jsonb),pos.ack_customer_sync(text,text,uuid,text,text,uuid,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.apply_customer_remote(text,text,uuid,jsonb,uuid,text,jsonb),pos.ack_customer_sync(text,text,uuid,text,text,uuid,bigint) TO pos_runtime;
-- END V9__persistent_customers.sql

-- BEGIN V10__item_customization.sql
-- Additive local customization policy; source catalogue and historical drafts remain intact.
CREATE TABLE pos.item_customization (
 branch_id integer PRIMARY KEY REFERENCES pos.catalogue_version(branch_id),
 rules jsonb NOT NULL CHECK(jsonb_typeof(rules)='object'),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_by uuid NOT NULL
);
GRANT SELECT ON pos.item_customization TO pos_runtime;
CREATE FUNCTION pos.apply_item_customization(proof text,terminal text,expected bigint,value jsonb) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;who uuid;version bigint;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 SELECT t.staff_id INTO who FROM pos.module_session t JOIN pos.staff s USING(branch_id,staff_id)
 WHERE t.branch_id=b AND t.token_hash=proof AND t.terminal_identity=terminal AND t.module='CATALOGUE'
 AND t.expires_at>clock_timestamp() AND s.enabled AND s.credential_version=t.credential_version;
 IF who IS NULL THEN RAISE EXCEPTION 'Catalogue session required' USING ERRCODE='28000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pos.admin_permissions(b,who) p WHERE p='module.catalogue') OR NOT EXISTS(SELECT 1 FROM pos.admin_permissions(b,who) p WHERE p='catalogue.manage') THEN RAISE EXCEPTION 'Catalogue edit permission required' USING ERRCODE='42501'; END IF;
 SELECT revision INTO version FROM pos.catalogue_version WHERE branch_id=b FOR UPDATE;
 IF version IS NULL OR version<>expected THEN RAISE EXCEPTION 'Catalogue changed; reload' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(value)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(value))<>4 OR NOT value ?& ARRAY['categoryExtras','swapGroups','items','combos'] THEN RAISE EXCEPTION 'Invalid customization rules' USING ERRCODE='23514'; END IF;
 INSERT INTO pos.item_customization VALUES(b,value,clock_timestamp(),who) ON CONFLICT(branch_id) DO UPDATE SET rules=value,updated_at=excluded.updated_at,updated_by=who;
 UPDATE pos.catalogue_version SET revision=revision+1 WHERE branch_id=b RETURNING revision INTO version;RETURN version;
END $$;
REVOKE ALL ON FUNCTION pos.apply_item_customization(text,text,bigint,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.apply_item_customization(text,text,bigint,jsonb) TO pos_runtime;
-- END V10__item_customization.sql

-- BEGIN V11__category_archive.sql
-- Catalogue definitions stay in their existing JSON records. Historical rows remain unchanged.
ALTER TABLE pos.catalogue_record ADD CONSTRAINT category_archive_state CHECK (
  source_type NOT IN ('menu_category','pizza_category') OR NOT (data ? 'archived') OR (
    jsonb_typeof(data->'archived')='boolean' AND
    (NOT (data->>'archived')::boolean OR NOT (data->>'active')::boolean)
  )
);
-- END V11__category_archive.sql

-- BEGIN V12__independent_store_identity.sql
-- Local POS database only. Never run against the cloud database.
ALTER TABLE pos.store_identity DROP CONSTRAINT store_identity_branch_id_check;
ALTER TABLE pos.store_identity ADD CONSTRAINT store_identity_positive_branch CHECK(branch_id>0);
ALTER TABLE pos.store_identity ADD COLUMN business_id uuid NOT NULL DEFAULT gen_random_uuid();
ALTER TABLE pos.store_identity ADD COLUMN store_uuid uuid NOT NULL DEFAULT gen_random_uuid();
ALTER TABLE pos.store_identity ADD COLUMN business_name varchar(200);
ALTER TABLE pos.store_identity ADD COLUMN store_name varchar(200);
ALTER TABLE pos.store_identity ADD COLUMN store_code varchar(40);
ALTER TABLE pos.store_identity ADD COLUMN address text NOT NULL DEFAULT '';
ALTER TABLE pos.store_identity ADD COLUMN phone varchar(64) NOT NULL DEFAULT '';
ALTER TABLE pos.store_identity ADD COLUMN email varchar(254) NOT NULL DEFAULT '';
ALTER TABLE pos.store_identity ADD COLUMN configuration jsonb NOT NULL DEFAULT '{}';
ALTER TABLE pos.store_identity ADD COLUMN opening_hours jsonb NOT NULL DEFAULT '{}';
ALTER TABLE pos.store_identity ADD COLUMN revision bigint NOT NULL DEFAULT 0;
ALTER TABLE pos.store_identity ADD COLUMN active boolean NOT NULL DEFAULT true;
ALTER TABLE pos.store_identity ADD COLUMN archived boolean NOT NULL DEFAULT false;
-- No invented historical name/timestamps. Existing numeric store identity is preserved.
CREATE TABLE pos.configuration_change (
 change_id uuid PRIMARY KEY, business_id uuid NOT NULL, store_id uuid, entity_type varchar(40) NOT NULL,
 entity_id uuid NOT NULL, operation varchar(10) NOT NULL CHECK(operation IN ('CREATE','UPDATE','DELETE')),
 fields jsonb NOT NULL, versions jsonb NOT NULL, state varchar(30) NOT NULL DEFAULT 'LOCAL_ONLY',
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE pos.integration_binding (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), enabled boolean NOT NULL DEFAULT false,
 endpoint text, cloud_business_id uuid, cloud_store_id uuid, terminal_id uuid,
 state varchar(30) NOT NULL DEFAULT 'DISABLED', configuration_cursor bigint NOT NULL DEFAULT 0,
 security_cursor bigint NOT NULL DEFAULT 0, security_confirmed_at timestamptz, next_retry timestamptz
);
INSERT INTO pos.integration_binding(singleton) VALUES(true);
GRANT SELECT ON pos.configuration_change,pos.integration_binding TO pos_runtime;
-- END V12__independent_store_identity.sql

-- BEGIN V13__store_audit_types.sql
INSERT INTO pos.audit_event_type(action,category,optional) VALUES
('LOCAL_STORE_CREATED','SYSTEM',false),('LOCAL_STORE_CHANGED','SYSTEM',false),('LOCAL_STORE_ADOPTED','SYSTEM',false);
-- END V13__store_audit_types.sql

-- BEGIN V14__local_store_management.sql
CREATE FUNCTION pos.manage_local_store(proof text,terminal text,expected bigint,value jsonb) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;who uuid;version bigint;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 SELECT t.staff_id INTO who FROM pos.module_session t JOIN pos.staff s USING(branch_id,staff_id)
 JOIN pos.store_owner o ON o.branch_id=t.branch_id AND o.staff_id=t.staff_id
 WHERE t.branch_id=b AND t.token_hash=proof AND t.terminal_identity=terminal AND t.module='ADMINISTRATION'
 AND t.expires_at>clock_timestamp() AND s.enabled AND s.credential_version=t.credential_version;
 IF who IS NULL OR NOT EXISTS(SELECT 1 FROM pos.admin_permissions(b,who) p WHERE p='module.administration')
 THEN RAISE EXCEPTION 'Designated local Owner required' USING ERRCODE='42501'; END IF;
 SELECT revision INTO version FROM pos.store_identity;
 IF version<>expected THEN RAISE EXCEPTION 'Store changed; reload' USING ERRCODE='40001'; END IF;
 IF jsonb_typeof(value)<>'object' OR value-ARRAY['businessName','name','code','address','phone','email','active']<>'{}'::jsonb
 OR value->>'name' IS NULL OR length(trim(value->>'name')) NOT BETWEEN 1 AND 200
 OR value->>'businessName' IS NULL OR length(trim(value->>'businessName')) NOT BETWEEN 1 AND 200
 OR value->>'code' IS NULL OR length(trim(value->>'code')) NOT BETWEEN 1 AND 40
 OR COALESCE(length(value->>'address'),0)>2000 OR COALESCE(length(value->>'phone'),0)>64 OR COALESCE(length(value->>'email'),0)>254
 OR NOT (value ? 'active') OR jsonb_typeof(value->'active')<>'boolean' THEN RAISE EXCEPTION 'Invalid store details' USING ERRCODE='23514'; END IF;
 UPDATE pos.store_identity SET business_name=trim(value->>'businessName'),store_name=trim(value->>'name'),store_code=trim(value->>'code'),
 address=COALESCE(value->>'address',''),phone=COALESCE(value->>'phone',''),email=COALESCE(value->>'email',''),
 active=(value->>'active')::boolean,revision=revision+1 RETURNING revision INTO version;
 RETURN version;
END $$;
REVOKE ALL ON FUNCTION pos.manage_local_store(text,text,bigint,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.manage_local_store(text,text,bigint,jsonb) TO pos_runtime;
-- END V14__local_store_management.sql

-- BEGIN V15__dynamic_customer_store.sql
-- Preserve existing profile snapshots; new profiles use the assigned store metadata.
CREATE OR REPLACE FUNCTION pos.write_customer(proof text,terminal text,id uuid,expected bigint,operation text,data jsonb,command uuid)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer;who uuid;previous pos.local_customer;next_revision bigint;stamp timestamptz;profile_value jsonb;name_value text;target pos.local_customer;k text;
BEGIN
 SELECT branch_id INTO b FROM pos.store_identity;
 PERFORM position FROM pos.stream_head WHERE branch_id=b FOR UPDATE;
 who=pos.require_customer_session(proof,terminal,CASE operation WHEN 'ARCHIVE' THEN 'customers.archive' WHEN 'BAN' THEN 'customers.ban' WHEN 'LINK' THEN 'customers.resolve' WHEN 'RESOLVE_SAVE' THEN 'customers.resolve' ELSE 'customers.manage' END);
 SELECT * INTO previous FROM pos.local_customer WHERE branch_id=b AND customer_id=id FOR UPDATE;
 IF operation IN ('SAVE','RESOLVE_SAVE') AND expected=-1 AND NOT FOUND THEN NULL;
 ELSIF NOT FOUND OR previous.revision<>expected OR previous.canonical_customer_id IS NOT NULL THEN
  RAISE EXCEPTION 'Customer changed; reload' USING ERRCODE='23514';
 END IF;
 IF EXISTS(SELECT 1 FROM pos.customer_alias WHERE alias_id=id AND customer_id<>id) THEN RAISE EXCEPTION 'Customer identity is already linked' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM pos.local_customer WHERE customer_id=id AND branch_id<>b) THEN RAISE EXCEPTION 'Foreign customer' USING ERRCODE='42501'; END IF;
 stamp=clock_timestamp();next_revision=coalesce(previous.revision+1,0);
 IF operation IN ('SAVE','RESOLVE_SAVE') THEN
  profile_value=data;
  IF jsonb_typeof(data)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each(data) v WHERE jsonb_typeof(value)<>'string' OR key NOT IN
   ('first_name','last_name','phone1','phone2','email','house_number','street','area','complex_name','preferred_store','city','postal_code','google_place_id','formatted_address','latitude','longitude','province','country')) THEN
   RAISE EXCEPTION 'Invalid profile fields' USING ERRCODE='23514'; END IF;
  name_value=btrim(coalesce(data->>'first_name','')||' '||coalesce(data->>'last_name',''));
  IF name_value='' OR coalesce(data->>'phone1','') !~ '^\+[1-9][0-9]{7,14}$' OR length(data->>'phone1')>20
   OR length(coalesce(data->>'email',''))>255 THEN RAISE EXCEPTION 'Invalid name or phone' USING ERRCODE='23514'; END IF;
  IF data->>'preferred_store' IS DISTINCT FROM coalesce(previous.profile->>'preferred_store',(SELECT COALESCE(s.store_name,(SELECT c.data->>'name' FROM pos.catalogue_record c WHERE c.branch_id=s.branch_id AND c.source_type='branch' LIMIT 1),'Store '||s.branch_id) FROM pos.store_identity s WHERE s.branch_id=b)) THEN
   RAISE EXCEPTION 'Only the customer changes preferred store' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM pos.local_customer WHERE branch_id=b AND customer_id<>id AND canonical_customer_id IS NULL AND profile->>'phone1'=data->>'phone1') THEN RAISE EXCEPTION 'Contact collision' USING ERRCODE='23505'; END IF;
  INSERT INTO pos.local_customer(customer_id,branch_id,display_name,phone,address,profile,normalized_phone,normalized_email,preferred_branch,global_id,revision,updated_at)
  VALUES(id,b,name_value,data->>'phone1',data->>'formatted_address',data,data->>'phone1',nullif(lower(btrim(data->>'email')),''),b,id,0,stamp)
  ON CONFLICT(customer_id) DO UPDATE SET display_name=excluded.display_name,phone=excluded.phone,address=excluded.address,
   profile=excluded.profile,normalized_phone=excluded.normalized_phone,normalized_email=excluded.normalized_email,revision=next_revision,updated_at=stamp,sync_state='PENDING';
  IF previous.profile IS NULL THEN UPDATE pos.local_customer SET field_times=jsonb_set(field_times,'{preferred_store}',to_jsonb(stamp)) WHERE customer_id=id; END IF;
  -- Address is one atomic timestamped group; other contact fields are individually versioned.
  FOR k IN SELECT key FROM jsonb_each(data) WHERE key NOT IN ('preferred_store','house_number','street','area','complex_name','city','postal_code','google_place_id','formatted_address','latitude','longitude','province','country') LOOP
   IF previous.profile->k IS DISTINCT FROM data->k THEN UPDATE pos.local_customer SET field_times=jsonb_set(field_times,ARRAY[k],to_jsonb(stamp)) WHERE customer_id=id; END IF;
  END LOOP;
  IF previous.profile IS NULL OR (previous.profile-ARRAY['first_name','last_name','phone1','phone2','email','preferred_store']) IS DISTINCT FROM (data-ARRAY['first_name','last_name','phone1','phone2','email','preferred_store']) THEN
   UPDATE pos.local_customer SET field_times=jsonb_set(field_times,'{address}',to_jsonb(stamp)) WHERE customer_id=id;
  END IF;
 ELSIF operation='ARCHIVE' THEN
  UPDATE pos.local_customer SET archived=(data->>'value')::boolean,revision=next_revision,updated_at=stamp WHERE customer_id=id;
 ELSIF operation='BAN' THEN
  IF coalesce((data->>'value')::boolean,true) AND length(btrim(coalesce(data->>'reason','')))=0 THEN RAISE EXCEPTION 'Ban reason required' USING ERRCODE='23514'; END IF;
  IF length(coalesce(data->>'reason',''))>2000 THEN RAISE EXCEPTION 'Reason too long' USING ERRCODE='23514'; END IF;
  UPDATE pos.local_customer SET banned=(data->>'value')::boolean,ban_reason=CASE WHEN (data->>'value')::boolean THEN data->>'reason' ELSE '' END,
    ban_changed_at=stamp,field_times=jsonb_set(field_times,'{ban}',to_jsonb(stamp)),revision=next_revision,updated_at=stamp,sync_state='PENDING' WHERE customer_id=id;
 ELSIF operation='LINK' THEN
  SELECT * INTO target FROM pos.local_customer WHERE branch_id=b AND customer_id=(data->>'target')::uuid AND canonical_customer_id IS NULL FOR UPDATE;
  IF NOT FOUND OR target.customer_id=id THEN RAISE EXCEPTION 'Invalid link target' USING ERRCODE='23514'; END IF;
  UPDATE pos.local_customer SET canonical_customer_id=target.customer_id,normalized_phone=NULL,normalized_email=NULL,revision=next_revision,updated_at=stamp WHERE customer_id=id;
  INSERT INTO pos.customer_alias VALUES(id,b,target.customer_id) ON CONFLICT(alias_id) DO UPDATE SET customer_id=excluded.customer_id;
  UPDATE pos.customer_alias SET customer_id=target.customer_id WHERE branch_id=b AND customer_id=id;
  UPDATE pos.local_customer SET canonical_customer_id=target.customer_id WHERE branch_id=b AND canonical_customer_id=id;
  IF previous.banned AND NOT target.banned THEN UPDATE pos.local_customer SET banned=true,ban_reason=previous.ban_reason,ban_changed_at=stamp,field_times=jsonb_set(field_times,'{ban}',to_jsonb(stamp)),revision=revision+1,sync_state='PENDING' WHERE customer_id=target.customer_id; END IF;
 ELSE RAISE EXCEPTION 'Unsupported customer operation' USING ERRCODE='23514';
 END IF;
 INSERT INTO pos.customer_status_history VALUES(command,b,id,operation,who,terminal,CASE WHEN operation='BAN' THEN coalesce(data->>'reason','') ELSE '' END,stamp,command);
 RETURN next_revision;
END $$;
-- END V15__dynamic_customer_store.sql

-- BEGIN V16__authentication_methods.sql
-- Credential authority remains the existing restricted provisioning paths. These triggers
-- preserve hashes verbatim while presenting an extensible method structure to readers.
ALTER TABLE pos.staff ADD COLUMN account_type varchar(10) NOT NULL DEFAULT 'LOCAL'
 CHECK(account_type IN ('LOCAL','CLOUD'));
CREATE TABLE pos.staff_auth_method (
 credential_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 branch_id integer NOT NULL, staff_id uuid NOT NULL,
 account_type varchar(10) NOT NULL CHECK(account_type IN ('LOCAL','CLOUD')),
 method varchar(20) NOT NULL CHECK(method IN ('PIN','PASSWORD','FINGERPRINT','RFID_NFC')),
 verifier text NOT NULL, lookup char(64), credential_version bigint NOT NULL,
 enabled boolean NOT NULL,
 FOREIGN KEY(branch_id,staff_id) REFERENCES pos.staff(branch_id,staff_id) ON DELETE CASCADE,
 UNIQUE(branch_id,staff_id,method),
 CHECK(method<>'PIN' OR lookup IS NOT NULL),
 CHECK(method IN ('PIN','PASSWORD') OR NOT enabled)
);
CREATE UNIQUE INDEX local_pin_unique ON pos.staff_auth_method(branch_id,lookup)
 WHERE method='PIN' AND account_type='LOCAL';
INSERT INTO pos.staff_auth_method(branch_id,staff_id,account_type,method,verifier,credential_version,enabled)
 SELECT branch_id,staff_id,account_type,'PASSWORD',password_hash,credential_version,enabled AND password_login_enabled FROM pos.staff;
INSERT INTO pos.staff_auth_method(branch_id,staff_id,account_type,method,verifier,lookup,credential_version,enabled)
 SELECT s.branch_id,s.staff_id,s.account_type,'PIN',p.hash,p.lookup,s.credential_version,s.enabled
 FROM pos.staff s JOIN pos.staff_pin p USING(branch_id,staff_id);
CREATE FUNCTION pos.refresh_auth_methods() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
DECLARE b integer; who uuid; s pos.staff;
BEGIN
 b=COALESCE(NEW.branch_id,OLD.branch_id); who=COALESCE(NEW.staff_id,OLD.staff_id);
 SELECT * INTO s FROM pos.staff WHERE branch_id=b AND staff_id=who;
 IF NOT FOUND THEN RETURN NULL; END IF;
 INSERT INTO pos.staff_auth_method(branch_id,staff_id,account_type,method,verifier,credential_version,enabled)
 VALUES(b,who,s.account_type,'PASSWORD',s.password_hash,s.credential_version,s.enabled AND s.password_login_enabled)
 ON CONFLICT(branch_id,staff_id,method) DO UPDATE SET account_type=excluded.account_type,verifier=excluded.verifier,credential_version=excluded.credential_version,enabled=excluded.enabled;
 IF EXISTS(SELECT 1 FROM pos.staff_pin WHERE branch_id=b AND staff_id=who) THEN
  INSERT INTO pos.staff_auth_method(branch_id,staff_id,account_type,method,verifier,lookup,credential_version,enabled)
  SELECT b,who,s.account_type,'PIN',hash,lookup,s.credential_version,s.enabled FROM pos.staff_pin WHERE branch_id=b AND staff_id=who
  ON CONFLICT(branch_id,staff_id,method) DO UPDATE SET account_type=excluded.account_type,verifier=excluded.verifier,lookup=excluded.lookup,credential_version=excluded.credential_version,enabled=excluded.enabled;
 ELSE
  DELETE FROM pos.staff_auth_method WHERE branch_id=b AND staff_id=who AND method='PIN';
 END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER staff_auth_methods AFTER INSERT OR UPDATE OF password_hash,password_login_enabled,credential_version,enabled,account_type ON pos.staff FOR EACH ROW EXECUTE FUNCTION pos.refresh_auth_methods();
CREATE TRIGGER pin_auth_methods AFTER INSERT OR UPDATE OR DELETE ON pos.staff_pin FOR EACH ROW EXECUTE FUNCTION pos.refresh_auth_methods();
CREATE TRIGGER invalidate_auth_methods AFTER INSERT OR UPDATE OR DELETE ON pos.staff_auth_method FOR EACH ROW EXECUTE FUNCTION pos.invalidate_module_access();
REVOKE ALL ON FUNCTION pos.refresh_auth_methods() FROM PUBLIC;
REVOKE ALL ON pos.staff_auth_method FROM PUBLIC,pos_runtime;
GRANT SELECT ON pos.staff_auth_method TO pos_runtime;
-- END V16__authentication_methods.sql

-- BEGIN V17__generic_item_recipe.sql
-- Generic recipes use the existing catalogue-record write port and identities.
-- Server validation checks menu_item and ingredient references before invoking that port.
ALTER TABLE pos.catalogue_record ADD CONSTRAINT generic_recipe_shape CHECK (
 source_type<>'menu_item_ingredient' OR (
 jsonb_typeof(data->'menu_item_id')='number' AND jsonb_typeof(data->'ingredient_id')='number'
 AND jsonb_typeof(data->'default_qty')='number' AND (data->>'default_qty')::integer>0
 AND jsonb_typeof(data->'is_removable')='boolean' AND jsonb_typeof(data->'sort_order')='number'
 ));

CREATE FUNCTION pos.guard_generic_recipe_references() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
BEGIN
 IF NEW.source_type='menu_item_ingredient' AND (
 NOT (NEW.data ?& ARRAY['menu_item_id','ingredient_id','default_qty','is_removable','sort_order']) OR
 NOT EXISTS(SELECT 1 FROM pos.catalogue_record WHERE branch_id=NEW.branch_id AND source_type='menu_item' AND data->'id'=NEW.data->'menu_item_id') OR
 NOT EXISTS(SELECT 1 FROM pos.catalogue_record WHERE branch_id=NEW.branch_id AND source_type='ingredient' AND data->'ingredient_id'=NEW.data->'ingredient_id')) THEN
 RAISE EXCEPTION 'Invalid generic recipe references' USING ERRCODE='23503'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER generic_recipe_references BEFORE INSERT OR UPDATE ON pos.catalogue_record FOR EACH ROW EXECUTE FUNCTION pos.guard_generic_recipe_references();
REVOKE ALL ON FUNCTION pos.guard_generic_recipe_references() FROM PUBLIC;
-- END V17__generic_item_recipe.sql

-- BEGIN V18__product_recipe_overrides.sql
-- PostgreSQL stores working recipe rows through the existing secured catalogue port.
ALTER TABLE pos.catalogue_record ADD CONSTRAINT burger_override_shape CHECK (
 source_type<>'burger_item_component_override' OR (
 data ?& ARRAY['burger_id','component_id','excluded','is_removable','sort_order']
 AND jsonb_typeof(data->'burger_id')='number'
 AND jsonb_typeof(data->'component_id')='number'
 AND jsonb_typeof(data->'excluded')='boolean'
 AND jsonb_typeof(data->'is_removable') IN ('boolean','null')
 AND jsonb_typeof(data->'sort_order') IN ('number','null')));

CREATE FUNCTION pos.guard_burger_override_references() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pos AS $$
BEGIN
 IF NEW.source_type='burger_item_component_override' AND (
 NOT EXISTS(SELECT 1 FROM pos.catalogue_record WHERE branch_id=NEW.branch_id AND source_type='menu_item' AND data->'id'=NEW.data->'burger_id') OR
 NOT EXISTS(SELECT 1 FROM pos.catalogue_record WHERE branch_id=NEW.branch_id AND source_type='burger_component' AND data->'component_id'=NEW.data->'component_id')) THEN
 RAISE EXCEPTION 'Invalid burger override references' USING ERRCODE='23503';
 END IF;
 RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER burger_override_references AFTER INSERT OR UPDATE ON pos.catalogue_record
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pos.guard_burger_override_references();
REVOKE ALL ON FUNCTION pos.guard_burger_override_references() FROM PUBLIC;

-- Aggregate creation inserts source parents and their links in one bulk statement.
-- PostgreSQL may reorder that INSERT's join output; check references at transaction commit,
-- just as a deferred foreign key, after every source row is visible.
DROP TRIGGER generic_recipe_references ON pos.catalogue_record;
CREATE CONSTRAINT TRIGGER generic_recipe_references AFTER INSERT OR UPDATE ON pos.catalogue_record
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pos.guard_generic_recipe_references();
-- END V18__product_recipe_overrides.sql

-- BEGIN V19__reporting_foundation.sql
-- V19__reporting_foundation.sql
-- OnlinePOS local PostgreSQL: additive reporting foundation after V18.
-- DO NOT alter, re-run, or checksum-change V1..V18 in an existing Flyway database.
-- Apply this file through Flyway against the LOCAL POS only.
-- IMPORTANT: The pre-existing pos.order_draft and pos.payment_metadata are
-- NOT completed sales or settled tender records. Nothing here turns them into sales.
-- All report_* financial facts start empty until trusted transaction code records
-- a finalized sale, refund, payment, cashup or stock movement.
-- Append-only fact tables are PROJECTIONS of verified business events. They must
-- not replace the transaction authority or its immutable command/outbox records.
-- The future application transaction layer must ingest through a trusted,
-- idempotent, authorized server-side path in the SAME ACID transaction as the
-- source event, or via a replay-safe outbox projection with reconciliation.
-- Never grant arbitrary report-fact INSERT privileges to cashier sessions.
-- Currency, business day and sale price/tax semantics are explicit, rather than
-- inferred from the current menu or the database server's timezone.

-- 1. Finished sale facts. A sale is recorded exactly once globally by event and
-- by originating business/store/transaction identifier.
CREATE TABLE pos.report_sale (
    sale_id uuid PRIMARY KEY,
    origin_event_id uuid NOT NULL UNIQUE,
    business_id uuid NOT NULL,
    store_id uuid NOT NULL,
    branch_id integer NOT NULL,
    source_system varchar(64) NOT NULL,
    source_transaction_id varchar(128) NOT NULL,
    receipt_number varchar(128),
    completed_at timestamptz NOT NULL,
    business_date date NOT NULL,
    currency char(3) NOT NULL DEFAULT 'ZAR',
    customer_id uuid,
    cashier_id uuid,
    terminal_identity varchar(512),
    order_channel varchar(64) NOT NULL DEFAULT 'IN_STORE',
    order_type varchar(64) NOT NULL DEFAULT 'SALE',
    -- Prices use an EXCLUSIVE-tax basis; any inclusive price must be normalized
    -- by the transaction authority before insertion.
    subtotal_excl_tax numeric(19,2) NOT NULL CHECK (subtotal_excl_tax >= 0),
    discount_excl_tax numeric(19,2) NOT NULL DEFAULT 0 CHECK (discount_excl_tax >= 0),
    tax_total numeric(19,2) NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
    service_fee_total numeric(19,2) NOT NULL DEFAULT 0 CHECK (service_fee_total >= 0),
    amount_due numeric(19,2) NOT NULL CHECK (amount_due >= 0),
    payment_policy varchar(24) NOT NULL DEFAULT 'IMMEDIATE'
        CHECK (payment_policy IN ('IMMEDIATE','ON_ACCOUNT','OTHER')),
    attributes jsonb NOT NULL DEFAULT '{}'::jsonb
        CHECK (jsonb_typeof(attributes) = 'object'),
    ingested_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT report_sale_unique_origin UNIQUE (business_id,store_id,source_system,source_transaction_id),
    CONSTRAINT report_sale_discount_limit CHECK (discount_excl_tax <= subtotal_excl_tax),
    CONSTRAINT report_sale_total_rule CHECK (
        amount_due = subtotal_excl_tax - discount_excl_tax + tax_total + service_fee_total
    ),
    CONSTRAINT report_sale_currency CHECK (currency ~ '^[A-Z]{3}$')
);
CREATE INDEX report_sale_day_store ON pos.report_sale(business_id,store_id,business_date,sale_id);
CREATE INDEX report_sale_day_branch ON pos.report_sale(branch_id,business_date,sale_id);
CREATE INDEX report_sale_customer ON pos.report_sale(business_id,customer_id,completed_at DESC)
    WHERE customer_id IS NOT NULL;
CREATE INDEX report_sale_cashier ON pos.report_sale(store_id,cashier_id,completed_at DESC)
    WHERE cashier_id IS NOT NULL;
CREATE INDEX report_sale_channel ON pos.report_sale(business_id,business_date,order_channel);

-- 2. Unified product facts, independent of pizza/burger/retail schema.
-- BUNDLE sales may have INCLUDED COMPONENT children. Count their quantities,
-- but NEVER count their line prices as additional revenue.
CREATE TABLE pos.report_sale_line (
    line_id uuid PRIMARY KEY,
    sale_id uuid NOT NULL REFERENCES pos.report_sale(sale_id) ON DELETE RESTRICT,
    parent_line_id uuid,
    line_kind varchar(20) NOT NULL CHECK (line_kind IN ('PRODUCT','BUNDLE','COMPONENT','ADDON')),
    revenue_role varchar(16) NOT NULL CHECK (revenue_role IN ('BILLABLE','INCLUDED')),
    source_type varchar(64) NOT NULL,
    source_id varchar(128) NOT NULL,
    -- A stable, canonical business-wide identifier, when one exists; otherwise
    -- reporting views namespace the local source ID by store to avoid collisions.
    global_product_key varchar(256),
    sku varchar(128),
    product_name varchar(256) NOT NULL,
    category_key varchar(128),
    category_name varchar(256),
    variant_key varchar(128) NOT NULL DEFAULT 'baseline',
    variant_name varchar(256),
    quantity numeric(19,3) NOT NULL CHECK (quantity > 0),
    unit varchar(24) NOT NULL DEFAULT 'each',
    unit_price_excl_tax numeric(19,4) NOT NULL CHECK (unit_price_excl_tax >= 0),
    gross_excl_tax numeric(19,2) NOT NULL CHECK (gross_excl_tax >= 0),
    discount_excl_tax numeric(19,2) NOT NULL DEFAULT 0 CHECK (discount_excl_tax >= 0),
    net_excl_tax numeric(19,2) NOT NULL CHECK (net_excl_tax >= 0),
    requires_cost_tracking boolean NOT NULL DEFAULT false,
    product_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb
        CHECK (jsonb_typeof(product_snapshot) = 'object'),
    UNIQUE(sale_id,line_id),
    CONSTRAINT report_line_parent_fk FOREIGN KEY(sale_id,parent_line_id)
        REFERENCES pos.report_sale_line(sale_id,line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT report_line_not_own_parent CHECK (parent_line_id IS NULL OR parent_line_id <> line_id),
    CONSTRAINT report_line_net_rule CHECK (net_excl_tax = gross_excl_tax - discount_excl_tax),
    CONSTRAINT report_line_included_free CHECK (
        revenue_role <> 'INCLUDED' OR
        (gross_excl_tax = 0 AND discount_excl_tax = 0 AND net_excl_tax = 0)
    )
);
CREATE INDEX report_line_sale ON pos.report_sale_line(sale_id);
CREATE INDEX report_line_product ON pos.report_sale_line(source_type,source_id,variant_key);
CREATE INDEX report_line_global_product ON pos.report_sale_line(global_product_key)
    WHERE global_product_key IS NOT NULL;
CREATE INDEX report_line_category ON pos.report_sale_line(category_key);

-- 3. Captured/confirmed tenders, not attempts or a payment-method suggestion.
-- Stable tender IDs must survive replay, cloud sync and Master failover.
CREATE TABLE pos.report_sale_tender (
    tender_id uuid PRIMARY KEY,
    source_event_id uuid NOT NULL UNIQUE,
    sale_id uuid NOT NULL REFERENCES pos.report_sale(sale_id) ON DELETE RESTRICT,
    captured_at timestamptz NOT NULL,
    business_date date NOT NULL,
    method varchar(64) NOT NULL,
    amount numeric(19,2) NOT NULL CHECK (amount > 0),
    external_reference varchar(256),
    provider varchar(64),
    attributes jsonb NOT NULL DEFAULT '{}'::jsonb
        CHECK (jsonb_typeof(attributes) = 'object')
);
CREATE INDEX report_tender_sale ON pos.report_sale_tender(sale_id);
CREATE INDEX report_tender_method ON pos.report_sale_tender(method,captured_at);

-- 4. Refunds are explicit negative financial events. Do not modify/delete
-- original completed sales. Refunds are reported on their OWN business date.
CREATE TABLE pos.report_refund (
    refund_id uuid PRIMARY KEY,
    origin_event_id uuid NOT NULL UNIQUE,
    sale_id uuid NOT NULL REFERENCES pos.report_sale(sale_id) ON DELETE RESTRICT,
    source_system varchar(64) NOT NULL,
    source_refund_id varchar(128) NOT NULL,
    refunded_at timestamptz NOT NULL,
    business_date date NOT NULL,
    -- These are positive values that the reporting views subtract.
    refunded_net_excl_tax numeric(19,2) NOT NULL CHECK(refunded_net_excl_tax >= 0),
    refunded_tax numeric(19,2) NOT NULL DEFAULT 0 CHECK(refunded_tax >= 0),
    refunded_fees numeric(19,2) NOT NULL DEFAULT 0 CHECK(refunded_fees >= 0),
    refunded_total numeric(19,2) NOT NULL CHECK(refunded_total > 0),
    employee_id uuid,
    reason varchar(512),
    attributes jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(attributes) = 'object'),
    ingested_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    UNIQUE(source_system,source_refund_id,sale_id),
    UNIQUE(refund_id,sale_id),
    CHECK(refunded_total = refunded_net_excl_tax + refunded_tax + refunded_fees)
);
CREATE INDEX report_refund_sale ON pos.report_refund(sale_id,refunded_at);
CREATE INDEX report_refund_date ON pos.report_refund(business_date,refund_id);

CREATE TABLE pos.report_refund_line (
    refund_line_id uuid PRIMARY KEY,
    refund_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    sale_line_id uuid NOT NULL,
    quantity numeric(19,3) NOT NULL CHECK(quantity > 0),
    refunded_net_excl_tax numeric(19,2) NOT NULL CHECK(refunded_net_excl_tax >= 0),
    -- Only reverse COGS if returned stock is reusable/actually credited.
    reversed_cogs numeric(19,2) NOT NULL DEFAULT 0 CHECK(reversed_cogs >= 0),
    FOREIGN KEY(refund_id,sale_id) REFERENCES pos.report_refund(refund_id,sale_id),
    FOREIGN KEY(sale_id,sale_line_id) REFERENCES pos.report_sale_line(sale_id,line_id)
);
CREATE INDEX report_refund_line_refund ON pos.report_refund_line(refund_id);
CREATE INDEX report_refund_line_source ON pos.report_refund_line(sale_line_id);

CREATE TABLE pos.report_refund_tender (
    refund_tender_id uuid PRIMARY KEY,
    source_event_id uuid NOT NULL UNIQUE,
    refund_id uuid NOT NULL REFERENCES pos.report_refund(refund_id) ON DELETE RESTRICT,
    refunded_at timestamptz NOT NULL,
    business_date date NOT NULL,
    method varchar(64) NOT NULL,
    amount numeric(19,2) NOT NULL CHECK(amount > 0),
    external_reference varchar(256)
);
CREATE INDEX report_refund_tender_refund ON pos.report_refund_tender(refund_id);

-- 5. Actual closed cashups with recorded float and counted amount.
CREATE TABLE pos.report_cashup (
    cashup_id uuid PRIMARY KEY,
    origin_event_id uuid NOT NULL UNIQUE,
    business_id uuid NOT NULL,
    store_id uuid NOT NULL,
    branch_id integer NOT NULL,
    terminal_identity varchar(512),
    employee_id uuid,
    period_start timestamptz NOT NULL,
    period_end timestamptz NOT NULL,
    business_date date NOT NULL,
    currency char(3) NOT NULL DEFAULT 'ZAR' CHECK(currency ~ '^[A-Z]{3}$'),
    opening_float numeric(19,2) NOT NULL DEFAULT 0 CHECK(opening_float >= 0),
    expected_cash numeric(19,2) NOT NULL CHECK(expected_cash >= 0),
    counted_cash numeric(19,2) NOT NULL CHECK(counted_cash >= 0),
    variance numeric(19,2) GENERATED ALWAYS AS (counted_cash - expected_cash) STORED,
    closed_at timestamptz NOT NULL,
    attributes jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(attributes) = 'object'),
    CHECK(period_end > period_start)
);
CREATE INDEX report_cashup_store_date ON pos.report_cashup(store_id,business_date,closed_at);

CREATE TABLE pos.report_cashup_tender (
    cashup_id uuid NOT NULL REFERENCES pos.report_cashup(cashup_id),
    tender_method varchar(64) NOT NULL,
    expected_amount numeric(19,2) NOT NULL CHECK(expected_amount >= 0),
    counted_amount numeric(19,2) CHECK(counted_amount >= 0),
    PRIMARY KEY(cashup_id,tender_method)
);

-- 6. Cost snapshots and inventory activity. No fabricated zero cost.
CREATE TABLE pos.report_sale_line_cost (
    line_id uuid PRIMARY KEY REFERENCES pos.report_sale_line(line_id),
    cost_total numeric(19,2) NOT NULL CHECK(cost_total >= 0),
    cost_method varchar(64) NOT NULL,
    cost_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(cost_snapshot) = 'object'),
    captured_at timestamptz NOT NULL
);

CREATE TABLE pos.report_stock_movement (
    movement_id uuid PRIMARY KEY,
    origin_event_id uuid NOT NULL UNIQUE,
    business_id uuid NOT NULL,
    store_id uuid NOT NULL,
    branch_id integer NOT NULL,
    source_item_type varchar(64) NOT NULL,
    source_item_id varchar(128) NOT NULL,
    item_name varchar(256) NOT NULL,
    movement_type varchar(40) NOT NULL,
    quantity_delta numeric(19,3) NOT NULL CHECK(quantity_delta <> 0),
    unit varchar(24) NOT NULL,
    unit_cost numeric(19,4) CHECK(unit_cost >= 0),
    occurred_at timestamptz NOT NULL,
    business_date date NOT NULL,
    source_sale_id uuid,
    reason varchar(512)
);
CREATE INDEX report_stock_item_date ON pos.report_stock_movement(store_id,source_item_type,source_item_id,business_date);

-- 7. User-configurable reports and monitoring (configuration, not financial facts).
CREATE TABLE pos.report_definition (
    report_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
    created_by uuid NOT NULL,
    name varchar(160) NOT NULL CHECK(length(btrim(name)) > 0),
    dataset varchar(64) NOT NULL,
    definition jsonb NOT NULL CHECK(jsonb_typeof(definition) = 'object'),
    shared boolean NOT NULL DEFAULT false,
    enabled boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    revision bigint NOT NULL DEFAULT 0 CHECK(revision >= 0)
);
CREATE INDEX report_definition_owner ON pos.report_definition(branch_id,created_by);

CREATE TABLE pos.report_alert_rule (
    rule_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    branch_id integer NOT NULL REFERENCES pos.store_identity(branch_id),
    created_by uuid NOT NULL,
    name varchar(160) NOT NULL,
    report_id uuid REFERENCES pos.report_definition(report_id),
    dataset varchar(64) NOT NULL,
    predicate jsonb NOT NULL CHECK(jsonb_typeof(predicate) = 'object'),
    enabled boolean NOT NULL DEFAULT true,
    last_evaluated_at timestamptz,
    last_triggered_at timestamptz
);

-- Optional sync/report projection freshness. No initial value is invented.
CREATE TABLE pos.report_projection_cursor (
    business_id uuid NOT NULL,
    store_id uuid NOT NULL,
    origin_system varchar(64) NOT NULL,
    last_source_position bigint CHECK(last_source_position >= 0),
    last_source_at timestamptz,
    last_ingested_at timestamptz,
    pending_events bigint CHECK(pending_events >= 0),
    PRIMARY KEY(business_id,store_id,origin_system)
);

-- 8. Universal financial event stream. Refunds are negative on refund date.
-- Use this event view for custom ranges and YTD, not order_draft or catalog prices.
CREATE VIEW pos.v_report_financial_events AS
SELECT s.business_id, s.store_id, s.branch_id, s.currency,
       s.sale_id AS event_id, s.sale_id, 'SALE'::text AS event_type,
       s.business_date, s.completed_at AS occurred_at,
       s.subtotal_excl_tax AS gross_excl_tax,
       s.discount_excl_tax AS discounts_excl_tax,
       0::numeric(19,2) AS returns_excl_tax,
       (s.subtotal_excl_tax - s.discount_excl_tax) AS net_sales_excl_tax,
       s.tax_total, s.service_fee_total, s.amount_due AS amount_incl_tax,
       1::bigint AS sale_count, 0::bigint AS refund_count
FROM pos.report_sale s
UNION ALL
SELECT s.business_id, s.store_id, s.branch_id, s.currency,
       r.refund_id AS event_id, s.sale_id, 'REFUND'::text AS event_type,
       r.business_date, r.refunded_at AS occurred_at,
       0::numeric(19,2), 0::numeric(19,2),
       r.refunded_net_excl_tax, -r.refunded_net_excl_tax, -r.refunded_tax, -r.refunded_fees,
       -r.refunded_total, 0::bigint, 1::bigint
FROM pos.report_refund r JOIN pos.report_sale s ON s.sale_id = r.sale_id;

CREATE VIEW pos.v_report_daily_sales AS
SELECT business_id,store_id,branch_id,currency,business_date,
       sum(sale_count)::bigint AS completed_sales,
       sum(refund_count)::bigint AS refunds,
       sum(gross_excl_tax)::numeric(19,2) AS gross_excl_tax,
       sum(discounts_excl_tax)::numeric(19,2) AS discount_excl_tax,
       sum(returns_excl_tax)::numeric(19,2) AS returns_excl_tax,
       sum(net_sales_excl_tax)::numeric(19,2) AS net_sales_excl_tax,
       sum(tax_total)::numeric(19,2) AS net_tax,
       sum(service_fee_total)::numeric(19,2) AS net_fees,
       sum(amount_incl_tax)::numeric(19,2) AS net_amount_incl_tax,
       sum(CASE WHEN event_type='SALE' THEN amount_incl_tax ELSE 0 END)::numeric(19,2)
           AS original_sale_amount_incl_tax
FROM pos.v_report_financial_events
GROUP BY business_id,store_id,branch_id,currency,business_date;

-- 9. Unified product activity. Refund line allocations are required for
-- item-level return accuracy. Financial totals remain sourced from headers.
CREATE VIEW pos.v_report_product_activity AS
SELECT s.business_id,s.store_id,s.branch_id,s.currency,s.business_date,
       l.line_id,s.sale_id,'SALE'::text AS event_type,
       coalesce(l.global_product_key,
           s.store_id::text||':'||l.source_type||':'||l.source_id) AS product_key,
       l.source_type,l.source_id,l.global_product_key,l.sku,l.product_name,
       l.category_key,l.category_name,l.variant_key,l.variant_name,
       l.line_kind,l.revenue_role,l.unit,
       l.quantity AS units,
       CASE WHEN l.revenue_role='BILLABLE' THEN l.net_excl_tax ELSE 0::numeric END AS revenue_excl_tax
FROM pos.report_sale_line l JOIN pos.report_sale s ON s.sale_id=l.sale_id
UNION ALL
SELECT s.business_id,s.store_id,s.branch_id,s.currency,r.business_date,
       l.line_id,s.sale_id,'REFUND'::text,
       coalesce(l.global_product_key,
           s.store_id::text||':'||l.source_type||':'||l.source_id),
       l.source_type,l.source_id,l.global_product_key,l.sku,l.product_name,
       l.category_key,l.category_name,l.variant_key,l.variant_name,
       l.line_kind,l.revenue_role,l.unit,
       -rl.quantity,
       -rl.refunded_net_excl_tax
FROM pos.report_refund_line rl
JOIN pos.report_refund r ON r.refund_id=rl.refund_id
JOIN pos.report_sale_line l ON l.line_id=rl.sale_line_id
JOIN pos.report_sale s ON s.sale_id=r.sale_id;

-- 10. Tender breakdown. Captured payments minus paid-out refunds.
CREATE VIEW pos.v_report_tender_activity AS
SELECT s.business_id,s.store_id,s.branch_id,s.currency,
       t.business_date,
       t.captured_at AS occurred_at,t.method,t.amount,'CAPTURE'::text AS event_type
FROM pos.report_sale_tender t JOIN pos.report_sale s ON s.sale_id=t.sale_id
UNION ALL
SELECT s.business_id,s.store_id,s.branch_id,s.currency,
       t.business_date,t.refunded_at,t.method,-t.amount,'REFUND'::text
FROM pos.report_refund_tender t
JOIN pos.report_refund r ON r.refund_id=t.refund_id
JOIN pos.report_sale s ON s.sale_id=r.sale_id;
-- Tender business dates are supplied by the trusted transaction authority
-- using the store’s configured cutoff and local timezone.

-- 11. Reconciliation checks. A mismatch is flagged, not silently corrected.
CREATE VIEW pos.v_report_sale_reconciliation AS
SELECT s.sale_id,s.business_id,s.store_id,s.business_date,s.currency,
       s.subtotal_excl_tax - s.discount_excl_tax AS header_net_excl_tax,
       coalesce(lines.total,0)::numeric(19,2) AS billed_lines_net_excl_tax,
       s.amount_due,
       coalesce(tenders.total,0)::numeric(19,2) AS captured_tenders,
       s.payment_policy,
       (abs((s.subtotal_excl_tax-s.discount_excl_tax)-coalesce(lines.total,0))>0.01)
           AS line_total_mismatch,
       (s.payment_policy='IMMEDIATE' AND abs(s.amount_due-coalesce(tenders.total,0))>0.01)
           AS payment_mismatch
FROM pos.report_sale s
LEFT JOIN LATERAL (
    SELECT sum(l.net_excl_tax) AS total FROM pos.report_sale_line l
    WHERE l.sale_id=s.sale_id AND l.revenue_role='BILLABLE'
) lines ON true
LEFT JOIN LATERAL (
    SELECT sum(t.amount) AS total FROM pos.report_sale_tender t WHERE t.sale_id=s.sale_id
) tenders ON true;

CREATE VIEW pos.v_report_refund_reconciliation AS
SELECT r.refund_id,r.sale_id,r.business_date,r.refunded_net_excl_tax,r.refunded_total,
       coalesce(lines.amount,0)::numeric(19,2) AS allocated_net_refund,
       coalesce(tenders.amount,0)::numeric(19,2) AS refunded_tender_amount,
       (abs(r.refunded_net_excl_tax-coalesce(lines.amount,0))>0.01) AS unallocated_refund_lines,
       (abs(r.refunded_total-coalesce(tenders.amount,0))>0.01) AS unmatched_refund_payout
FROM pos.report_refund r
LEFT JOIN LATERAL (
   SELECT sum(rl.refunded_net_excl_tax) AS amount
   FROM pos.report_refund_line rl WHERE rl.refund_id=r.refund_id
) lines ON true
LEFT JOIN LATERAL (
   SELECT sum(t.amount) AS amount
   FROM pos.report_refund_tender t WHERE t.refund_id=r.refund_id
) tenders ON true;

-- 12. Available TODAY with existing V1..V18 records: drafts, not sales.
CREATE VIEW pos.v_report_draft_activity AS
SELECT d.branch_id,d.sync_id AS draft_id,d.customer_id,d.state,
       d.created_at,d.total,d.provisional_reference,
       count(l.line_id)::bigint AS line_count,
       coalesce(sum(l.quantity),0)::bigint AS total_units
FROM pos.order_draft d
LEFT JOIN pos.order_line l ON l.branch_id=d.branch_id AND l.order_id=d.sync_id
GROUP BY d.branch_id,d.sync_id,d.customer_id,d.state,d.created_at,d.total,d.provisional_reference;

-- 12a. Existing audit activity is useful before a completed-sale ledger exists.
CREATE VIEW pos.v_report_staff_audit_activity AS
SELECT a.branch_id,a.audit_id,a.actor_id,a.username_snapshot,
       a.action,a.entity_type,a.transaction_id,a.terminal_identity,
       a.occurred_at,a.source_system
FROM pos.audit_record a;

-- 12b. Product-cost coverage. If no cost-tracked lines exist or expected
-- costs are missing, do not show a fictitious gross profit.
CREATE VIEW pos.v_report_sale_cost_coverage AS
SELECT s.sale_id,s.business_id,s.store_id,s.business_date,
       count(l.line_id) FILTER (WHERE l.requires_cost_tracking)::bigint AS tracked_lines,
       count(l.line_id) FILTER (WHERE l.requires_cost_tracking AND c.line_id IS NULL)::bigint AS missing_cost_lines,
       sum(c.cost_total)::numeric(19,2) AS known_cost_total,
       CASE WHEN count(l.line_id) FILTER (WHERE l.requires_cost_tracking)>0
                  AND count(l.line_id) FILTER (WHERE l.requires_cost_tracking AND c.line_id IS NULL)=0
            THEN (s.subtotal_excl_tax-s.discount_excl_tax)-coalesce(sum(c.cost_total),0)
            ELSE NULL END::numeric(19,2) AS gross_profit_when_complete
FROM pos.report_sale s
LEFT JOIN pos.report_sale_line l ON l.sale_id=s.sale_id
LEFT JOIN pos.report_sale_line_cost c ON c.line_id=l.line_id
GROUP BY s.sale_id,s.business_id,s.store_id,s.business_date,
         s.subtotal_excl_tax,s.discount_excl_tax;

-- 13. Owner-specified inclusive start/end dates with exclusive boundary inside.
-- Each currency is queried separately. No mixed-currency fake totals.
CREATE FUNCTION pos.report_sales_summary(
    p_start_date date,p_end_date date,p_currency text DEFAULT 'ZAR',
    p_business_id uuid DEFAULT NULL,p_store_id uuid DEFAULT NULL)
RETURNS TABLE (
    completed_sales bigint, refunds bigint, gross_excl_tax numeric,
    discount_excl_tax numeric,returns_excl_tax numeric,net_sales_excl_tax numeric,net_tax numeric,
    net_fees numeric,net_amount_incl_tax numeric,average_original_sale numeric)
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pos AS $$
BEGIN
  IF p_start_date IS NULL OR p_end_date IS NULL OR p_end_date < p_start_date
     OR p_currency IS NULL OR upper(p_currency) !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'Valid dates and three-letter currency required' USING ERRCODE='22023';
  END IF;
  RETURN QUERY
  SELECT coalesce(sum(e.sale_count),0)::bigint,
         coalesce(sum(e.refund_count),0)::bigint,
         coalesce(sum(e.gross_excl_tax),0),coalesce(sum(e.discounts_excl_tax),0),
         coalesce(sum(e.returns_excl_tax),0),coalesce(sum(e.net_sales_excl_tax),0),coalesce(sum(e.tax_total),0),
         coalesce(sum(e.service_fee_total),0),coalesce(sum(e.amount_incl_tax),0),
         round(sum(CASE WHEN e.event_type='SALE' THEN e.amount_incl_tax ELSE 0 END)
               / nullif(sum(e.sale_count),0),2)
  FROM pos.v_report_financial_events e
  WHERE e.business_date >= p_start_date
    AND e.business_date < (p_end_date + 1)
    AND e.currency=upper(p_currency)
    AND (p_business_id IS NULL OR e.business_id=p_business_id)
    AND (p_store_id IS NULL OR e.store_id=p_store_id);
END $$;

-- 14. Demand trends. Compares daily rates for periods of different length.
-- Both positive sales and negative line-level returns count toward quantity.
-- Use only returned items with report_refund_line detail for complete trends.
CREATE FUNCTION pos.report_product_trends(
    p_current_start date,p_current_end date,
    p_previous_start date,p_previous_end date,
    p_currency text DEFAULT 'ZAR',p_business_id uuid DEFAULT NULL,p_store_id uuid DEFAULT NULL)
RETURNS TABLE (
    business_id uuid,product_key text,product_name text,category_name text,variant_key text,
    current_units numeric,previous_units numeric,
    current_revenue_excl_tax numeric,previous_revenue_excl_tax numeric,
    current_daily_units numeric,previous_daily_units numeric,
    growth_percent numeric,trend text)
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pos AS $$
BEGIN
  IF p_current_start IS NULL OR p_current_end IS NULL OR p_previous_start IS NULL OR p_previous_end IS NULL
     OR p_current_start>p_current_end OR p_previous_start>p_previous_end
     OR p_currency IS NULL OR upper(p_currency) !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'Valid current/previous date ranges and currency required' USING ERRCODE='22023';
  END IF;
  RETURN QUERY
  WITH grouped AS (
    SELECT a.business_id, a.product_key,
           max(a.product_name)::text AS name_value,
           max(a.category_name)::text AS category_value,
           a.variant_key,
           sum(CASE WHEN a.business_date BETWEEN p_current_start AND p_current_end THEN a.units ELSE 0 END) AS curr_units,
           sum(CASE WHEN a.business_date BETWEEN p_previous_start AND p_previous_end THEN a.units ELSE 0 END) AS prev_units,
           sum(CASE WHEN a.business_date BETWEEN p_current_start AND p_current_end THEN a.revenue_excl_tax ELSE 0 END) AS curr_revenue,
           sum(CASE WHEN a.business_date BETWEEN p_previous_start AND p_previous_end THEN a.revenue_excl_tax ELSE 0 END) AS prev_revenue
    FROM pos.v_report_product_activity a
    WHERE ((a.business_date BETWEEN p_current_start AND p_current_end)
           OR (a.business_date BETWEEN p_previous_start AND p_previous_end))
      AND a.currency=upper(p_currency)
      AND (p_business_id IS NULL OR a.business_id=p_business_id)
      AND (p_store_id IS NULL OR a.store_id=p_store_id)
      -- Exclude bundle parents from unit rankings to avoid counting both a bundle
      -- and its included components as equivalent units. BUNDLE revenue remains
      -- available in separate sales/category reports.
      AND a.line_kind <> 'BUNDLE'
    GROUP BY a.business_id,a.product_key,a.variant_key
  ), rates AS (
    SELECT g.*,
           (g.curr_units/(p_current_end-p_current_start+1))::numeric AS curr_daily,
           (g.prev_units/(p_previous_end-p_previous_start+1))::numeric AS prev_daily
    FROM grouped g
  )
  SELECT r.business_id,r.product_key,r.name_value,r.category_value,r.variant_key::text,
         r.curr_units,r.prev_units,r.curr_revenue,r.prev_revenue,
         round(r.curr_daily,3),round(r.prev_daily,3),
         round(100*(r.curr_daily-r.prev_daily)/nullif(r.prev_daily,0),2),
         CASE WHEN r.prev_units=0 AND r.curr_units>0 THEN 'NEW'
              WHEN r.curr_units<=0 AND r.prev_units>0 THEN 'STOPPED'
              WHEN r.curr_units+r.prev_units<10 THEN 'LOW_VOLUME'
              WHEN r.prev_daily>0 AND r.curr_daily>=r.prev_daily*1.2 THEN 'GROWING'
              WHEN r.prev_daily>0 AND r.curr_daily<=r.prev_daily*0.8 THEN 'DECLINING'
              ELSE 'STABLE' END::text
  FROM rates r
  ORDER BY abs(r.curr_daily-r.prev_daily) DESC,r.name_value;
END $$;

-- 15. Immutable posted financial facts: corrections are compensating refunds/
-- adjustments in the transaction authority, never UPDATE/DELETE of history.
CREATE FUNCTION pos.guard_report_history() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pos AS $$
BEGIN
    RAISE EXCEPTION 'Posted reporting facts are append-only' USING ERRCODE='42501';
END $$;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'report_sale','report_sale_line','report_sale_tender','report_refund',
    'report_refund_line','report_refund_tender','report_cashup',
    'report_cashup_tender','report_sale_line_cost','report_stock_movement'
  ] LOOP
    EXECUTE format('CREATE TRIGGER report_immutable_change BEFORE UPDATE OR DELETE ON pos.%I FOR EACH STATEMENT EXECUTE FUNCTION pos.guard_report_history()',t);
    EXECUTE format('CREATE TRIGGER report_immutable_truncate BEFORE TRUNCATE ON pos.%I FOR EACH STATEMENT EXECUTE FUNCTION pos.guard_report_history()',t);
  END LOOP;
END $$;
REVOKE ALL ON FUNCTION pos.guard_report_history() FROM PUBLIC;

-- 16. No financial-fact write rights from the interactive runtime DB role.
-- A separate, explicitly authorized transaction projector is required later.
REVOKE ALL ON pos.report_sale,pos.report_sale_line,pos.report_sale_tender,
    pos.report_refund,pos.report_refund_line,pos.report_refund_tender,
    pos.report_cashup,pos.report_cashup_tender,pos.report_sale_line_cost,
    pos.report_stock_movement,pos.report_definition,pos.report_alert_rule,
    pos.report_projection_cursor FROM PUBLIC,pos_runtime;
GRANT SELECT ON pos.report_sale,pos.report_sale_line,pos.report_sale_tender,
    pos.report_refund,pos.report_refund_line,pos.report_refund_tender,
    pos.report_cashup,pos.report_cashup_tender,pos.report_sale_line_cost,
    pos.report_stock_movement,pos.report_definition,pos.report_alert_rule,
    pos.report_projection_cursor TO pos_runtime;
GRANT SELECT ON pos.v_report_financial_events,pos.v_report_daily_sales,
    pos.v_report_product_activity,pos.v_report_tender_activity,
    pos.v_report_sale_reconciliation,pos.v_report_refund_reconciliation,
    pos.v_report_draft_activity,pos.v_report_staff_audit_activity,
    pos.v_report_sale_cost_coverage TO pos_runtime;
REVOKE ALL ON FUNCTION pos.report_sales_summary(date,date,text,uuid,uuid),
    pos.report_product_trends(date,date,date,date,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pos.report_sales_summary(date,date,text,uuid,uuid),
    pos.report_product_trends(date,date,date,date,text,uuid,uuid) TO pos_runtime;

-- NOTE ON PERMISSIONS: The Java backend must validate module.reports and
-- store/business scope before invoking these SELECTs/functions. A shared
-- pos_runtime login is not a substitute for per-staff authorization.
-- NOTE ON COSTS: Do not assign the same inventory cost to BOTH a bundle parent
-- and its included component children. Each actual cost is attributed once.
-- NOTE ON CONSISTENCY: Projector must reject or flag mismatched sale totals,
-- duplicate source IDs, over-refunds, missing refund allocations and missing
-- cost snapshots before marking a business-day financial report reconciled.

-- END V19__reporting_foundation.sql

COMMIT;
